import { posthog } from "@/config/posthog";

/** Logs expected, best-effort failures during development only. */
export function logDevWarning(scope: string, error: unknown): void {
  if (__DEV__) {
    console.warn(`[${scope}]`, error);
  }
}

// A URI or an absolute path with at least two segments, through the end of the line.
const PATH_PATTERN = /(^|[\s"'(=])(?:[a-z][a-z\d+.-]*:\/\/|\/[^\s/]+\/)[^\n]*/gim;

/** File paths can contain attachment names, so a message keeps only the text before its first path. */
function redactPaths(text: string): string {
  return text.replace(PATH_PATTERN, "$1<path>");
}

function toReportableError(error: unknown): Error {
  if (!(error instanceof Error)) return new Error(redactPaths(String(error)));
  const message = redactPaths(error.message);
  const reportable = new Error(message);
  reportable.name = error.name;
  reportable.stack = error.stack?.replace(error.message, () => message);
  return reportable;
}

/**
 * Reports an unexpected failure to error tracking. PostHog does not capture
 * console output, so anything worth tracking must go through here. Show the
 * user a plain message separately, never the error text.
 */
export function reportError(
  scope: string,
  error: unknown,
  properties: Record<string, string | number | boolean | null> = {}
): void {
  logDevWarning(scope, error);
  posthog?.captureException(toReportableError(error), { scope, ...properties });
}

        accessibilityLabel="Edit"
      >
        <Feather name="edit-2" size={metrics.iconMd} color={colors.text} />
      </Pressable>
      <Pressable
        onPress={() => setDetailsOpen(true)}
        hitSlop={space.md}
        style={({ pressed }) => pressed && press}
        accessibilityRole="button"
        accessibilityLabel="Entry details"
      >
        <Feather name="more-vertical" size={metrics.iconMd} color={colors.textSecondary} />
      </Pressable>
    </View>
  ) : existing ? (
    <Pressable
      onPress={() => {
        draft.reset();
        media.reset(existing);
        setMode("view");
      }}
      hitSlop={space.md}
      style={({ pressed }) => pressed && press}
      accessibilityRole="button"
      accessibilityLabel="Cancel"
    >
      <Feather name="x" size={metrics.iconLg} color={colors.textSecondary} />
    </Pressable>
  ) : undefined;

  const handleSave = async () => {
    const outcome = await draft.save();
    const entryProperties = {
      has_text: draft.text.trim().length > 0,
      image_count: media.images.length,
      audio_count: media.audios.length,
      file_count: media.attachments.length,
      has_location: Boolean(location.on && location.place),
    };

    if (outcome === "created") {
      analytics.capture("entry_created", entryProperties);
      navigation.goBack();
    } else if (outcome === "updated") {
      analytics.capture("entry_updated", entryProperties);
      setMode("view");
    }
  };

  const handleLocationPress = async () => {
    await location.request();
    keepFocus();
  };

  const handleLocationRefresh = async () => {
    await location.refresh();
    keepFocus();
  };

  const handleLocationRemove = () => {
    location.remove();
    keepFocus();
  };

  return (
    <Layout.Screen style={[styles.screen, { backgroundColor: colors.background }]}>
      <ScreenHeader title={title} onBack={() => navigation.goBack()} right={headerRight} />

      <DateTimeBadges
        when={draft.when}
        onOpenDate={isReadOnly ? undefined : () => setDatePickerOpen(true)}
        onOpenTime={isReadOnly ? undefined : () => setTimePickerOpen(true)}
        location={location.place}
        locationOn={location.on}
        locationLoading={location.loading}
        locationFailed={location.failed}
        onLocationPress={isReadOnly ? undefined : handleLocationPress}
        onLocationRefresh={isReadOnly ? undefined : handleLocationRefresh}
        onLocationRemove={isReadOnly ? undefined : handleLocationRemove}
        readOnly={isReadOnly}
      />

      <View style={styles.tags}>
        {draft.tags.map((tag) => (
          <TagChip
            key={tag.id}
            tag={tag}
            onPress={isReadOnly ? () => openTag(tag.id) : undefined}
            onRemove={
              isReadOnly
                ? undefined
                : () => draft.setTags((tags) => tags.filter((item) => item.id !== tag.id))
            }
          />
        ))}
        {!isReadOnly ? (
          <Pressable
            onPress={() => setTagsOpen(true)}
            hitSlop={space.xs}
            style={({ pressed }) => [
              styles.addTag,
              { borderColor: colors.separator },
              pressed && press,
            ]}
            accessibilityLabel="Add tags"
            accessibilityRole="button"
          >
            <Feather name="tag" size={metrics.iconXs} color={colors.textSecondary} />
            <ThemedText
              weight="medium"
              style={[styles.addTagText, { color: colors.textSecondary }]}
            >
              Tags
            </ThemedText>
          </Pressable>
        ) : null}
      </View>

      <Layout.Screen.Body>
        <Layout.Screen.Main>
          <ComposeEditor
            inputRef={inputRef}
            value={draft.text}
            onChangeText={draft.setText}
            readOnly={isReadOnly}
          >
            {isReadOnly ? (
              <ComposeAttachments
                imageUris={media.images}
                onRemoveImage={media.removeImage}
                audioUris={media.audios}
                onRemoveAudio={media.removeAudio}
                attachments={media.attachments}
                onRemoveAttachment={media.removeAttachment}
                readOnly
              />
            ) : null}
          </ComposeEditor>
        </Layout.Screen.Main>

        {!isReadOnly ? (
          <Layout.Screen.Footer>
            <ComposeAttachments
              imageUris={media.images}
              onRemoveImage={media.removeImage}
              audioUris={media.audios}
              onRemoveAudio={media.removeAudio}
              attachments={media.attachments}
              onRemoveAttachment={media.removeAttachment}
              readOnly={false}
            />
            <ComposeFooterBar
              imageCount={media.images.length}
              attachmentCount={media.attachments.length}
              isRecording={media.isRecording}
              canSave={draft.canSave}
              recordingDurationMs={media.recordingDurationMs}
              recordingLevels={media.recordingLevels}
              onPickImage={async () => {
                await media.pickImage();
                keepFocus();
              }}
              onPickAttachments={async () => {
                await media.pickAttachments();
                keepFocus();
              }}
              onToggleRecording={async () => {
                await media.toggleRecording();
                keepFocus();
              }}
              onSave={handleSave}
            />
          </Layout.Screen.Footer>
        ) : null}
      </Layout.Screen.Body>

      <CalendarPicker
        visible={datePickerOpen}
        selectedDate={draft.when}
        onSelectDate={(dayTs) => draft.setWhen((prev) => withTimeOfDay(dayTs, prev))}
        onClose={() => setDatePickerOpen(false)}
      />

      <TimePicker
        visible={timePickerOpen}
        value={draft.when}
        onChange={draft.setWhen}
        onClose={() => setTimePickerOpen(false)}
      />

      <TagPicker
        visible={tagsOpen}
        selected={draft.tags}
        onChange={draft.setTags}
        onClose={() => setTagsOpen(false)}
      />

      {existing ? (
        <EntryDetailsModal
          entry={existing}
          visible={detailsOpen}
          onClose={() => setDetailsOpen(false)}
          onEdit={() => setMode("edit")}
          onDelete={async () => {
            try {
              await removeEntry(existing.id);
            } catch (error) {
              reportError("entry:delete", error);
              Alert.alert("Could not delete", "Try again.");
              return;
            }
            analytics.capture("entry_deleted", {
              has_text: Boolean(existing.text?.trim()),
              image_count: existing.images.length,
              audio_count: existing.audios.length,
              file_count: existing.attachments.length,
              has_location: Boolean(existing.location),
            });
            navigation.goBack();
          }}
        />
      ) : null}
    </Layout.Screen>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
  },
  headerActions: {
    flexDirection: "row",
    alignItems: "center",
