import { migrateToV1 } from "./migrations/v1.ts";

export interface SchemaDatabase {
  execAsync(source: string): Promise<void>;
  getFirstAsync<T>(source: string, ...params: unknown[]): Promise<T | null>;
  getAllAsync<T>(source: string, ...params: unknown[]): Promise<T[]>;
  withTransactionAsync(task: () => Promise<void>): Promise<void>;
}

interface DatabaseMigration {
  version: number;
  up: (db: SchemaDatabase, schema: string) => Promise<void>;
}

/**
 * Add one immutable file per forward schema change, then register it here.
 * Never edit a migration that has shipped or renumber an existing version.
 */
const MIGRATIONS: readonly DatabaseMigration[] = [{ version: 1, up: migrateToV1 }];

export const DATABASE_SCHEMA_VERSION = MIGRATIONS[MIGRATIONS.length - 1].version;

async function readSchemaVersion(db: SchemaDatabase, schema: string): Promise<number> {
  const result = await db.getFirstAsync<{ user_version: number }>(`PRAGMA ${schema}.user_version`);
  return result?.user_version ?? 0;
}

async function applyMigrations(
  db: SchemaDatabase,
  currentVersion: number,
  minimumVersion: number,
  schema: string
): Promise<void> {
  if (currentVersion < minimumVersion) {
    throw new Error(`Unsupported database version (${currentVersion}).`);
  }
  if (currentVersion > DATABASE_SCHEMA_VERSION) {
    throw new Error(`Unsupported database version (${currentVersion}). Update OpenLog.`);
  }

  const pending = MIGRATIONS.filter((migration) => migration.version > currentVersion);
  for (const migration of pending) {
    await db.withTransactionAsync(async () => {
      await migration.up(db, schema);
      await db.execAsync(`PRAGMA ${schema}.user_version = ${migration.version}`);
    });
  }
}

/** Opens a fresh database at v1, or moves an existing supported database forward. */
export async function migrateDatabaseSchema(db: SchemaDatabase): Promise<void> {
  await applyMigrations(db, await readSchemaVersion(db, "main"), 0, "main");
}

export async function initializeDatabaseSchema(db: SchemaDatabase): Promise<void> {
  await db.execAsync(`
    PRAGMA journal_mode = WAL;
    PRAGMA synchronous = NORMAL;
    PRAGMA busy_timeout = 5000;
    PRAGMA foreign_keys = OFF;
  `);

  await migrateDatabaseSchema(db);

  // Foreign keys stay off until migrations finish: the pragma is a no-op
  // inside a transaction, and enabled constraints block table rebuilds.
  await db.execAsync("PRAGMA foreign_keys = ON;");

  await initializeSearchIndex(db);
}

export async function recreateSearchIndex(db: SchemaDatabase, schema: string): Promise<void> {
  await db.execAsync(`
    DROP TRIGGER IF EXISTS ${schema}.entries_fts_ai;
    DROP TRIGGER IF EXISTS ${schema}.entries_fts_ad;
    DROP TRIGGER IF EXISTS ${schema}.entries_fts_au;
    DROP TABLE IF EXISTS ${schema}.entries_fts;
    CREATE VIRTUAL TABLE ${schema}.entries_fts USING fts5(
      text,
      location,
      content='entries',
      content_rowid='rowid'
    );
    CREATE TRIGGER ${schema}.entries_fts_ai AFTER INSERT ON entries BEGIN
      INSERT INTO entries_fts (rowid, text, location)
      VALUES (new.rowid, new.text, new.location);
    END;
    CREATE TRIGGER ${schema}.entries_fts_ad AFTER DELETE ON entries BEGIN
      INSERT INTO entries_fts (entries_fts, rowid, text, location)
      VALUES ('delete', old.rowid, old.text, old.location);
    END;
    CREATE TRIGGER ${schema}.entries_fts_au AFTER UPDATE ON entries BEGIN
      INSERT INTO entries_fts (entries_fts, rowid, text, location)
      VALUES ('delete', old.rowid, old.text, old.location);
      INSERT INTO entries_fts (rowid, text, location)
      VALUES (new.rowid, new.text, new.location);
    END;
    INSERT INTO ${schema}.entries_fts(entries_fts) VALUES ('rebuild');
  `);
}

async function initializeSearchIndex(db: SchemaDatabase): Promise<void> {
  const searchIndexObjects = [
    "entries_fts",
    "entries_fts_ai",
    "entries_fts_ad",
    "entries_fts_au",
  ] as const;
  const placeholders = searchIndexObjects.map(() => "?").join(", ");
  const existing = await db.getAllAsync<{ name: string }>(
    `SELECT name FROM sqlite_master WHERE name IN (${placeholders})`,
    ...searchIndexObjects
  );
  const hadCompleteIndex = existing.length === searchIndexObjects.length;

  if (!hadCompleteIndex) {
    await recreateSearchIndex(db, "main");
  }
}

import * as SQLite from "expo-sqlite";
import { initializeDatabaseSchema } from "./schema";

const DB_NAME = "app.db";

let dbInstance: SQLite.SQLiteDatabase | null = null;
let openPromise: Promise<SQLite.SQLiteDatabase> | null = null;
let chain: Promise<unknown> = Promise.resolve();

function withLock<T>(fn: () => Promise<T>): Promise<T> {
  const next = chain.then(fn, fn);
  chain = next.then(
    () => undefined,
    () => undefined
  );
  return next;
}

/** Runs an operation under the database lock to serialize with active transactions. */
export async function withDatabaseLock<T>(fn: () => Promise<T>): Promise<T> {
  return withLock(fn);
}

async function openFreshDatabase(): Promise<SQLite.SQLiteDatabase> {
  const db = await SQLite.openDatabaseAsync(DB_NAME);
  await initializeDatabaseSchema(db);
  return db;
}

async function ensureDatabase(): Promise<SQLite.SQLiteDatabase> {
  if (dbInstance) return dbInstance;

  if (!openPromise) {
    openPromise = openFreshDatabase()
      .then((db) => {
        dbInstance = db;
        return db;
      })
      .finally(() => {
        openPromise = null;
      });
  }

  return openPromise;
}

/**
 * Opens (and lazily initialises) the app's single SQLite database.
 * Prefer {@link runDb} so access stays serialized.
 */
export async function getDatabase(): Promise<SQLite.SQLiteDatabase> {
  return withLock(ensureDatabase);
}

/**
 * Runs a database operation. Work is serialized to avoid Android NPEs from
 * concurrent open/exec calls during startup or fast refresh.
 */
export async function runDb<T>(fn: (db: SQLite.SQLiteDatabase) => Promise<T>): Promise<T> {
  return withLock(async () => {
    const db = await ensureDatabase();
    return await fn(db);
  });
}

import type * as SQLite from "expo-sqlite";
import { mediaFileUri } from "@/services/media/storage";
import type { Entry, EntryLocation, NewEntryInput, Tag, UpdateEntryInput } from "@/shared/types";
import { addMonths, startOfDay, startOfMonth } from "@/shared/utils/dates";
import { runDb } from "./database";
import { buildPagedEntryQuery, type EntryCursor, type PagedEntriesOptions } from "./pagination";
import { MAX_TAGS_PER_ENTRY } from "./tags";
import { parseAttachments, parseUris } from "./uris";
import { extractMediaFilenameFromUri, mediaNameKey } from "./validation";

export interface EntryRecord {
  id: string;
  created_at: number;
  updated_at: number;
  text: string | null;
  images: string | null;
  audios: string | null;
  attachments: string | null;
  latitude: number | null;
  longitude: number | null;
  location: string | null;
}

const ENTRY_COLUMNS =
  "id, created_at, updated_at, text, images, audios, attachments, latitude, longitude, location";

function parseLocation(row: EntryRecord): EntryLocation | undefined {
  if (row.latitude == null || row.longitude == null) return undefined;
  return {
    latitude: row.latitude,
    longitude: row.longitude,
    name: row.location ?? undefined,
  };
}

/** Maps a database row onto the app-side {@link Entry} shape, resolving stored filenames to live file URIs. */
export function toEntry(row: EntryRecord, tags: Tag[] = []): Entry {
  return {
    id: row.id,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    text: row.text ?? undefined,
    images: row.images ? parseUris(row.images).map(mediaFileUri) : [],
    audios: row.audios ? parseUris(row.audios).map(mediaFileUri) : [],
    attachments: row.attachments
      ? parseAttachments(row.attachments).map((attachment) => ({
          ...attachment,
          uri: mediaFileUri(attachment.uri),
        }))
      : [],
    tags,
    location: parseLocation(row),
  };
}

interface EntryTagRecord {
  entry_id: string;
  id: string;
  name: string;
  color_id: Tag["colorId"];
}

export async function getTagsByEntryIds(
  db: SQLite.SQLiteDatabase,
  entryIds: string[]
): Promise<Map<string, Tag[]>> {
  const result = new Map<string, Tag[]>();
  if (!entryIds.length) return result;
  const placeholders = entryIds.map(() => "?").join(", ");
  const rows = await db.getAllAsync<EntryTagRecord>(
    `SELECT et.entry_id, t.id, t.name, t.color_id
       FROM entry_tags et
       JOIN tags t ON t.id = et.tag_id
      WHERE et.entry_id IN (${placeholders})
      ORDER BY t.name COLLATE NOCASE, t.id`,
    ...entryIds
  );
  for (const row of rows) {
    const tags = result.get(row.entry_id) ?? [];
    tags.push({ id: row.id, name: row.name, colorId: row.color_id });
    result.set(row.entry_id, tags);
  }
  return result;
}

function tagIds(input?: string[]): string[] {
  const ids = [...new Set(input ?? [])];
  if (ids.length > MAX_TAGS_PER_ENTRY) {
    throw new Error(`An entry can have at most ${MAX_TAGS_PER_ENTRY} tags.`);
  }
  return ids;
}

async function replaceEntryTags(db: SQLite.SQLiteDatabase, entryId: string, ids: string[]) {
  await db.runAsync("DELETE FROM entry_tags WHERE entry_id = ?", [entryId]);
  for (const tagId of ids) {
    await db.runAsync("INSERT INTO entry_tags (entry_id, tag_id) VALUES (?, ?)", [entryId, tagId]);
  }
}

function locationParams(location?: EntryLocation | null) {
  return [location?.latitude ?? null, location?.longitude ?? null, location?.name ?? null] as const;
}

export type { EntryCursor, PagedEntriesOptions } from "./pagination";

export interface PagedEntriesResult {
  entries: Entry[];
  nextCursor?: EntryCursor;
  hasMore: boolean;
}

/** Cursor-paginated entries with prefetch support. */
export async function getPagedEntries(
  options: PagedEntriesOptions = {}
): Promise<PagedEntriesResult> {
  const { limit = 50 } = options;
  return runDb(async (db) => {
    const page = buildPagedEntryQuery(ENTRY_COLUMNS, options);
    const rows = await db.getAllAsync<EntryRecord>(page.query, ...page.params, limit + 1);
    const hasMore = rows.length > limit;
    const resultRows = hasMore ? rows.slice(0, limit) : rows;
    const tagsByEntryId = await getTagsByEntryIds(
      db,
      resultRows.map((row) => row.id)
    );
    const entries = resultRows.map((row) => toEntry(row, tagsByEntryId.get(row.id)));
    const last = entries[entries.length - 1];
    const nextCursor: EntryCursor | undefined =
      hasMore && last ? { createdAt: last.createdAt, id: last.id } : undefined;

    return {
      entries,
      nextCursor,
      hasMore,
    };
  });
}

/** Single entry lookup by ID from SQLite. */
export async function getEntryById(id: string): Promise<Entry | null> {
  return runDb(async (db) => {
    const row = await db.getFirstAsync<EntryRecord>(
      `SELECT ${ENTRY_COLUMNS} FROM entries WHERE id = ?`,
      id
    );
    if (!row) return null;
    const tagsByEntryId = await getTagsByEntryIds(db, [id]);
    return toEntry(row, tagsByEntryId.get(id));
  });
}

/** Lightweight timestamp scan to highlight active days in a month without loading full entries. */
export async function getEntryDaysForMonth(monthTs: number): Promise<Set<number>> {
  const start = startOfMonth(monthTs);
  const end = addMonths(monthTs, 1);
  return runDb(async (db) => {
    const rows = await db.getAllAsync<{ created_at: number }>(
      `SELECT created_at FROM entries WHERE created_at >= ? AND created_at < ?`,
      start,
      end
    );
    const days = new Set<number>();
    for (const row of rows) {
      days.add(startOfDay(row.created_at));
    }
    return days;
  });
}

/** All entries (bounded optionally by limit), newest first. */
export async function getEntries(limit?: number): Promise<Entry[]> {
  return runDb(async (db) => {
    const query = limit
      ? `SELECT ${ENTRY_COLUMNS} FROM entries ORDER BY created_at DESC, id DESC LIMIT ?`
      : `SELECT ${ENTRY_COLUMNS} FROM entries ORDER BY created_at DESC, id DESC`;
    const rows = limit
      ? await db.getAllAsync<EntryRecord>(query, limit)
      : await db.getAllAsync<EntryRecord>(query);
    const tagsByEntryId = await getTagsByEntryIds(
      db,
      rows.map((row) => row.id)
    );
    return rows.map((row) => toEntry(row, tagsByEntryId.get(row.id)));
  });
}

export type { NewEntryInput, UpdateEntryInput };

/** Inserts a new entry and returns the created record. */
export async function createEntry(input: NewEntryInput): Promise<Entry> {
  return runDb(async (db) => {
    const id =
      typeof crypto !== "undefined" && "randomUUID" in crypto
        ? crypto.randomUUID()
        : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
    const createdAt = input.createdAt ?? Date.now();
    const updatedAt = createdAt;
    const [lat, lng, locationName] = locationParams(input.location);
    const images = input.images?.length ? input.images : [];
    const audios = input.audios?.length ? input.audios : [];
    const ids = tagIds(input.tagIds);

    await db.withTransactionAsync(async () => {
      await db.runAsync(
        `INSERT INTO entries (
         id, created_at, updated_at, text, images, audios, attachments,
         latitude, longitude, location
       ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        id,
        createdAt,
        updatedAt,
        input.text || null,
        images.length ? JSON.stringify(images) : null,
        audios.length ? JSON.stringify(audios) : null,
        input.attachments?.length ? JSON.stringify(input.attachments) : null,
        lat,
        lng,
        locationName
      );
      await replaceEntryTags(db, id, ids);
    });

    const tagsByEntryId = await getTagsByEntryIds(db, [id]);

    return {
      id,
      createdAt,
      updatedAt,
      text: input.text || undefined,
      images: images.map(mediaFileUri),
      audios: audios.map(mediaFileUri),
      attachments: (input.attachments ?? []).map((attachment) => ({
        ...attachment,
        uri: mediaFileUri(attachment.uri),
      })),
      tags: tagsByEntryId.get(id) ?? [],
      location: input.location ?? undefined,
    };
  });
}

/** Updates fields on an existing entry. */
export async function updateEntry(id: string, input: UpdateEntryInput): Promise<Entry> {
  return runDb(async (db) => {
    const row = await db.getFirstAsync<EntryRecord>(
      `SELECT ${ENTRY_COLUMNS} FROM entries WHERE id = ?`,
      id
    );

    if (!row) {
      throw new Error("Entry not found");
    }

    const updatedAt = Date.now();
    const createdAt = input.createdAt ?? row.created_at;
    const text = input.text !== undefined ? input.text || null : row.text;
    const [lat, lng, locationName] =
      input.location !== undefined
        ? locationParams(input.location)
        : ([row.latitude, row.longitude, row.location] as const);

    const imagesJson =
      input.images !== undefined
        ? input.images.length
          ? JSON.stringify(input.images)
          : null
        : row.images;

    const audiosJson =
      input.audios !== undefined
        ? input.audios.length
          ? JSON.stringify(input.audios)
          : null
        : row.audios;

    const filesJson =
      input.attachments !== undefined
        ? input.attachments.length
          ? JSON.stringify(input.attachments)
          : null
        : row.attachments;

    await db.withTransactionAsync(async () => {
      await db.runAsync(
        `UPDATE entries
          SET created_at = ?,
              updated_at = ?,
              text = ?,
              images = ?,
              audios = ?,
              attachments = ?,
              latitude = ?,
              longitude = ?,
              location = ?
        WHERE id = ?`,
        createdAt,
        updatedAt,
        text,
        imagesJson,
        audiosJson,
        filesJson,
        lat,
        lng,
        locationName,
        id
      );
      if (input.tagIds !== undefined) {
        await replaceEntryTags(db, id, tagIds(input.tagIds));
      }
    });

    const tagsByEntryId = await getTagsByEntryIds(db, [id]);

    return toEntry(
      {
        id,
        created_at: createdAt,
        updated_at: updatedAt,
        text,
        images: imagesJson,
        audios: audiosJson,
        attachments: filesJson,
        latitude: lat,
        longitude: lng,
        location: locationName,
      },
      tagsByEntryId.get(id)
    );
  });
}

interface MediaRow {
  images: string | null;
  audios: string | null;
  attachments: string | null;
}

function extractMediaUrisFromRow(row?: MediaRow | null): string[] {
  if (!row) return [];
  const mediaUris: string[] = [];
  if (row.images) mediaUris.push(...parseUris(row.images));
  if (row.audios) mediaUris.push(...parseUris(row.audios));
  if (row.attachments) {
    mediaUris.push(...parseAttachments(row.attachments).map((attachment) => attachment.uri));
  }
  return mediaUris;
}

export async function deleteEntry(id: string): Promise<string[]> {
  return runDb(async (db) => {
    const row = await db.getFirstAsync<MediaRow>(
      `SELECT images, audios, attachments FROM entries WHERE id = ?`,
      id
    );
    await db.runAsync(`DELETE FROM entries WHERE id = ?`, id);
    return extractMediaUrisFromRow(row);
  });
}

/** Removes every entry and tag; media files are deleted separately, against the committed state. */
export async function deleteAllEntries(): Promise<void> {
  await runDb((db) =>
    db.withTransactionAsync(async () => {
      await db.runAsync(`DELETE FROM entries`);
      await db.runAsync(`DELETE FROM tags`);
    })
  );
}

/**
 * Returns the given media filenames that no entry stores. Every quoted string in the media
 * columns counts as a reference, compared by `mediaNameKey`, so shared, legacy, escaped, and
 * case-variant names keep their files.
 */
export async function filterUnreferencedMedia(uris: string[]): Promise<string[]> {
  if (!uris.length) return [];

  return runDb(async (db) => {
    const rows = await db.getAllAsync<MediaRow>(`SELECT images, audios, attachments FROM entries`);
    // Every quoted string counts, even in a malformed column, so a damaged row still protects its files.
    const referenced = new Set<string>();
    for (const row of rows) {
      for (const column of [row.images, row.audios, row.attachments]) {
        if (typeof column !== "string") continue;
        for (const [literal] of column.matchAll(/"(?:[^"\\]|\\.)*"/g)) {
          referenced.add(mediaNameKey(literal.slice(1, -1)));
          try {
            const value: unknown = JSON.parse(literal);
            if (typeof value !== "string") continue;
            referenced.add(mediaNameKey(value));
            const filename = extractMediaFilenameFromUri(value);
            if (filename) referenced.add(mediaNameKey(filename));
          } catch {
            // The raw text above is already recorded.
          }
        }
      }
    }

    const unreferenced: string[] = [];
    const seen = new Set<string>();
    for (const uri of uris) {
      const filename = extractMediaFilenameFromUri(uri) ?? uri.trim();
      if (!filename || seen.has(filename)) continue;
      seen.add(filename);
      if (!referenced.has(mediaNameKey(filename))) unreferenced.push(filename);
    }

    return unreferenced;
  });
}

import {
  ACCENT_KEY,
  EDITOR_TEXT_SIZE_KEY,
  FONT_KEY,
  MOTION_LEVEL_KEY,
  ONBOARDING_COMPLETED_KEY,
  parseUserPreferences,
  SHOW_LOCATION_KEY,
  SHOW_TIMESTAMP_KEY,
  TEXT_SIZE_KEY,
  THEME_KEY,
  TIMELINE_DENSITY_KEY,
  TIMELINE_STYLE_KEY,
  USER_NAME_KEY,
  type UserPreferences,
} from "@/theme/preferences";
import { runDb } from "./database";

export async function getSetting(key: string, fallback: string): Promise<string> {
  return runDb(async (db) => {
    const row = await db.getFirstAsync<{ value: string }>(
      `SELECT value FROM settings WHERE key = ?`,
      key
    );
    return row?.value ?? fallback;
  });
}

export async function setSetting(key: string, value: string): Promise<void> {
  await runDb(async (db) => {
    await db.runAsync(
      `INSERT INTO settings (key, value) VALUES (?, ?)
       ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
      key,
      value
    );
  });
}

export async function setSettingsBatch(entries: Record<string, string>): Promise<void> {
  const records = Object.entries(entries);
  if (records.length === 0) return;

  await runDb(async (db) => {
    await db.withTransactionAsync(async () => {
      for (const [key, value] of records) {
        await db.runAsync(
          `INSERT INTO settings (key, value) VALUES (?, ?)
           ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
          key,
          value
        );
      }
    });
  });
}

export async function getAllUserPreferences(): Promise<{
  userName: string | null;
  onboardingCompleted: boolean;
  preferences: UserPreferences;
}> {
  return runDb(async (db) => {
    const rows = await db.getAllAsync<{ key: string; value: string }>(
      `SELECT key, value FROM settings`
    );
    const map = new Map<string, string>();
    for (const r of rows) map.set(r.key, r.value);

    const userName = map.get(USER_NAME_KEY)?.trim() || null;
    const preferences = parseUserPreferences(map);

    return {
      userName,
      onboardingCompleted: map.get(ONBOARDING_COMPLETED_KEY) === "1",
      preferences,
    };
  });
}

export async function getUserName(): Promise<string | null> {
  return runDb(async (db) => {
    const row = await db.getFirstAsync<{ value: string }>(
      `SELECT value FROM settings WHERE key = ?`,
      USER_NAME_KEY
    );
    const value = row?.value?.trim();
    return value || null;
  });
}

export async function setUserName(name: string): Promise<void> {
  const trimmed = name.trim();
  await runDb(async (db) => {
    if (!trimmed) {
      await db.runAsync(`DELETE FROM settings WHERE key = ?`, USER_NAME_KEY);
      return;
    }

    await db.runAsync(
      `INSERT INTO settings (key, value) VALUES (?, ?)
       ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
      USER_NAME_KEY,
      trimmed
    );
  });
}

