content.text:
import { File, FileMode, Paths } from "expo-file-system";
import { strToU8, Zip, ZipDeflate, ZipPassThrough } from "fflate";

import { runDb } from "@/services/db/database";
import { parseAttachments, parseUris } from "@/services/db/uris";
import { mediaDirectory } from "@/services/media/storage";
import { APP_VERSION } from "@/shared/utils/appInfo";
import { reportError } from "@/shared/utils/devLog";
import {
  acquireExportGate,
  assertBackupArchiveSize,
  assertBackupExportSizeLimits,
  BACKUP_YIELD_BYTES,
  releaseExportGate,
  waitForImportGate,
} from "../utils";
import {
  ARCHIVE_EXTENSION,
  ARCHIVE_FORMAT,
  ARCHIVE_SCHEMA_VERSION,
  type BackupEntry,
  type BackupLocation,
  type BackupManifest,
  type BackupTag,
  type BackupTimelineData,
  type ExportBackupOptions,
  type ExportBackupResult,
  MANIFEST_FILENAME,
  TIMELINE_DATA_FILENAME,
} from "../utils/types";

const CHUNK_SIZE = 256 * 1024;

export class MissingBackupMediaError extends Error {
  constructor(missingCount: number) {
    const missing =
      missingCount === 1
        ? "1 file attached to your entries is missing from this device. A backup without it"
        : `${missingCount.toLocaleString()} files attached to your entries are missing from this device. A backup without them`;
    super(`${missing} couldn’t be restored, so it wasn’t saved.`);
    this.name = "MissingBackupMediaError";
  }
}

/**
 * Media files the timeline references; unreferenced files on disk are never exported.
 * Import rejects an archive whose timeline references absent media, so a missing file fails the export.
 */
function referencedMediaFiles(entries: readonly BackupEntry[]): File[] {
  const dir = mediaDirectory();
  const filenames = new Set(
    entries.flatMap((entry) => [
      ...(entry.images ?? []),
      ...(entry.audios ?? []),
      ...(entry.attachments ?? []).map((attachment) => attachment.uri),
    ])
  );
  const files = [...filenames].map((filename) => new File(dir, filename));
  const missingCount = files.filter((file) => !file.exists).length;
  if (missingCount > 0) {
    reportError("backup:exportMissingMedia", new Error("Referenced media is missing."), {
      missing_count: missingCount,
    });
    throw new MissingBackupMediaError(missingCount);
  }
  return files;
}

interface ArchiveReadProgress {
  bytesSinceYield: number;
}

async function addFileToArchive({
  zip,
  archivePath,
  sourceFile,
  progress,
  signal,
}: {
  zip: Zip;
  archivePath: string;
  sourceFile: File;
  progress: ArchiveReadProgress;
  signal?: AbortSignal;
}): Promise<void> {
  if (!sourceFile.exists) {
    reportError("backup:exportMissingMedia", new Error("Media disappeared during backup."));
    throw new MissingBackupMediaError(1);
  }
  const archiveFile = new ZipPassThrough(archivePath);
  zip.add(archiveFile);
  const source = sourceFile.open(FileMode.ReadOnly);
  try {
    const size = source.size ?? 0;
    let read = 0;
    while (read < size) {
      if (signal?.aborted) throw new Error("Backup cancelled");
      const chunk = source.readBytes(Math.min(CHUNK_SIZE, size - read));
      if (chunk.length === 0) {
        if (read < size) {
          throw new Error("A media file changed while it was being backed up.");
        }
        break;
      }
      read += chunk.length;
      archiveFile.push(chunk, read === size);
      progress.bytesSinceYield += chunk.length;
      if (progress.bytesSinceYield >= BACKUP_YIELD_BYTES) {
        progress.bytesSinceYield = 0;
        await new Promise((resolve) => setTimeout(resolve, 0));
      }
    }
    if (size === 0) archiveFile.push(new Uint8Array(0), true);
  } finally {
    source.close();
  }
}

/**
 * Creates a ZIP archive that contains manifest.json, timeline.json, and the media files.
 */
export async function exportBackupArchive(
  options?: ExportBackupOptions
): Promise<ExportBackupResult> {
  if (options?.signal?.aborted) throw new Error("Backup cancelled");

  await waitForImportGate();
  const createdAt = Date.now();
  const filename = `openlog-backup-${new Date(createdAt).toISOString().replace(/[:.]/g, "-")}${ARCHIVE_EXTENSION}`;
  const exportFile = new File(Paths.cache, filename);
  exportFile.create({ overwrite: true });
  const output = exportFile.open(FileMode.WriteOnly);
  let succeeded = false;
  let gateHeld = false;

  try {
    // Exports are counted, so only an acquire this call made may be released.
    acquireExportGate();
    gateHeld = true;
    const { tags, entries, settings } = await runDb(async (db) => {
      const tagRows = await db.getAllAsync<{
        id: string;
        name: string;
        key: string;
        color_id: string;
        created_at: number;
        updated_at: number;
      }>(
        "SELECT id, name, key, color_id, created_at, updated_at FROM tags ORDER BY name COLLATE NOCASE, id"
      );
      const mappedTags: BackupTag[] = tagRows.map((row) => ({
        id: row.id,
        name: row.name,
        key: row.key,
        colorId: row.color_id,
        createdAt: row.created_at,
        updatedAt: row.updated_at,
      }));

      const entryTagRows = await db.getAllAsync<{
        entry_id: string;
        tag_id: string;
      }>("SELECT entry_id, tag_id FROM entry_tags ORDER BY entry_id, tag_id");
      const tagIdsByEntryId = new Map<string, string[]>();
      for (const row of entryTagRows) {
        const existing = tagIdsByEntryId.get(row.entry_id) ?? [];
        existing.push(row.tag_id);
        tagIdsByEntryId.set(row.entry_id, existing);
      }

      const entryRows = await db.getAllAsync<{
        id: string;
        created_at: number;
        updated_at: number;
        text: string | null;
        images: string | null;
        audios: string | null;
        attachments: string | null;
        latitude: number | null;
        longitude: number | null;
        location: string | null;
      }>(
        "SELECT id, created_at, updated_at, text, images, audios, attachments, latitude, longitude, location FROM entries ORDER BY created_at DESC, id DESC"
      );

      const mappedEntries: BackupEntry[] = entryRows.map((row) => {
        const images = parseUris(row.images);
        const audios = parseUris(row.audios);
        const attachments = parseAttachments(row.attachments).map((att) => ({
          uri: att.uri,
          name: att.name,
          size: att.size,
          mimeType: att.mime,
        }));

        const location: BackupLocation | null =
          row.latitude != null && row.longitude != null
            ? {
                latitude: row.latitude,
                longitude: row.longitude,
                name: row.location ?? undefined,
              }
            : null;

        return {
          id: row.id,
          createdAt: row.created_at,
          updatedAt: row.updated_at,
          text: row.text ?? null,
          images: images.length > 0 ? images : undefined,
          audios: audios.length > 0 ? audios : undefined,
          attachments: attachments.length > 0 ? attachments : undefined,
          tagIds: tagIdsByEntryId.get(row.id),
          location,
        };
      });

      const settingRows = await db.getAllAsync<{
        key: string;
        value: string;
      }>("SELECT key, value FROM settings ORDER BY key");
      const mappedSettings: Record<string, string> = {};
      for (const row of settingRows) {
        mappedSettings[row.key] = row.value;
      }

      return {
        tags: mappedTags,
        entries: mappedEntries,
        settings: mappedSettings,
      };
    });

    options?.onProgress?.(entries.length, entries.length, "entries");
    if (options?.signal?.aborted) throw new Error("Backup cancelled");

    const mediaFiles = referencedMediaFiles(entries);

    const manifest: BackupManifest = {
      format: ARCHIVE_FORMAT,
      version: ARCHIVE_SCHEMA_VERSION,
      createdAt,
      appVersion: APP_VERSION ?? "1.0.0",
      counts: {
        entry: entries.length,
        tag: tags.length,
        media: mediaFiles.length,
      },
    };

    const timelineData: BackupTimelineData = {
      tags,
      entries,
      settings: Object.keys(settings).length > 0 ? settings : undefined,
    };

    const manifestBytes = strToU8(JSON.stringify(manifest));
    const timelineBytes = strToU8(JSON.stringify(timelineData));
    assertBackupExportSizeLimits({
      manifestBytes: manifestBytes.length,
      timelineBytes: timelineBytes.length,
      mediaBytes: mediaFiles.map((file) => file.info().size ?? 0),
    });

    let archiveBytes = 0;
    let archiveError: Error | null = null;
    const zip = new Zip((error, chunk) => {
      if (error) {
        archiveError = error;
        return;
      }
      if (archiveError) return;
      try {
        assertBackupArchiveSize(archiveBytes + chunk.length);
      } catch (sizeError) {
        archiveError = sizeError instanceof Error ? sizeError : new Error(String(sizeError));
        return;
      }
      output.writeBytes(chunk);
      archiveBytes += chunk.length;
    });

    const manifestFile = new ZipDeflate(MANIFEST_FILENAME, { level: 6 });
    zip.add(manifestFile);
    manifestFile.push(manifestBytes, true);

    const timelineJsonFile = new ZipDeflate(TIMELINE_DATA_FILENAME, { level: 6 });
    zip.add(timelineJsonFile);
    timelineJsonFile.push(timelineBytes, true);

    const progress: ArchiveReadProgress = { bytesSinceYield: 0 };
    for (let index = 0; index < mediaFiles.length; index++) {
      if (options?.signal?.aborted) throw new Error("Backup cancelled");
      const mediaFile = mediaFiles[index];
      await addFileToArchive({
        zip,
        archivePath: `media/${mediaFile.name}`,
        sourceFile: mediaFile,
        progress,
        signal: options?.signal,
      });
      options?.onProgress?.(index + 1, mediaFiles.length, "media");
    }

    if (options?.signal?.aborted) throw new Error("Backup cancelled");
    zip.end();
    if (archiveError) throw archiveError;
    succeeded = true;

    return {
      fileUri: exportFile.uri,
      filename,
      counts: {
        entry: entries.length,
        tag: tags.length,
        media: mediaFiles.length,
      },
      byteSize: archiveBytes,
    };
  } finally {
    if (gateHeld) releaseExportGate();
    output.close();
    if (!succeeded && exportFile.exists) exportFile.delete();
  }
}

import { Directory, File, FileMode, Paths } from "expo-file-system";
import * as FileSystem from "expo-file-system/legacy";
import { defaultDatabaseDirectory } from "expo-sqlite";
import { strFromU8, Unzip, UnzipInflate, UnzipPassThrough } from "fflate";

import { notifyStoreReload } from "@/modules/entry/store/EntryStore";
import { runDb } from "@/services/db/database";
import { mediaNameKey } from "@/services/db/validation";
import { discardAllDrafts } from "@/services/drafts/store";
import { mediaDirectory } from "@/services/media/storage";
import { logDevWarning, reportError } from "@/shared/utils/devLog";
import {
  acquireImportGate,
  assertBackupCounts,
  assertBackupManifest,
  assertBackupMediaReferences,
  assertBackupTimelineData,
  BACKUP_LIMITS,
  BACKUP_YIELD_BYTES,
  calculateRequiredImportBytes,
  extractMediaFilename,
  releaseImportGate,
  validateArchivePath,
  waitForExportGate,
} from "../utils";
import {
  type ImportBackupOptions,
  type ImportBackupResult,
  MANIFEST_FILENAME,
  TIMELINE_DATA_FILENAME,
} from "../utils/types";
import { replaceTimelineData } from "./timeline";

function getExistingTimelineDiskBytes(): number {
  let bytes = 0;
  try {
    if (defaultDatabaseDirectory) {
      const dbDirUri = defaultDatabaseDirectory.startsWith("file://")
        ? defaultDatabaseDirectory
        : `file://${defaultDatabaseDirectory}`;
      for (const suffix of ["", "-wal", "-shm"] as const) {
        const file = new File(dbDirUri, `app.db${suffix}`);
        if (file.exists) bytes += file.info().size ?? 0;
      }
    }
  } catch {
    // ignore
  }
  try {
    const mediaDir = mediaDirectory();
    if (mediaDir.exists) {
      for (const item of mediaDir.list()) {
        if (item instanceof File && item.exists) {
          bytes += item.info().size ?? 0;
        }
      }
    }
  } catch {
    // ignore
  }
  return bytes;
}

function concat(chunks: Uint8Array[]): Uint8Array {
  const size = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
  const result = new Uint8Array(size);
  let offset = 0;
  for (const chunk of chunks) {
    result.set(chunk, offset);
    offset += chunk.length;
  }
  return result;
}

function deleteLiveMedia(filenames: readonly string[]): void {
  const directory = mediaDirectory();
  for (const filename of filenames) {
    try {
      const file = new File(directory, filename);
      if (file.exists) file.delete();
    } catch (error) {
      reportError("backup:deleteLiveMedia", error);
    }
  }
}

/**
 * Moves staged media beside the live files and returns the names it added.
 * Media files are immutable and UUID-named, so an existing name already holds that file.
 */
async function publishStagedMedia(
  stagedMedia: Directory,
  mediaNames: ReadonlySet<string>
): Promise<string[]> {
  const live = mediaDirectory();
  live.create({ idempotent: true, intermediates: true });
  const added: string[] = [];
  try {
    for (const filename of mediaNames) {
      const destination = new File(live, filename);
      if (destination.exists) continue;
      await new File(stagedMedia, filename).move(destination);
      added.push(filename);
    }
    for (const filename of mediaNames) {
      if (!new File(live, filename).exists) {
        throw new Error("Import media verification failed.");
      }
    }
  } catch (error) {
    deleteLiveMedia(added);
    throw error;
  }
  return added;
}

/** Removes media the restored timeline does not use. Best effort: leftovers are only unreferenced files. */
function pruneReplacedMedia(mediaNames: ReadonlySet<string>): void {
  try {
    const live = mediaDirectory();
    if (!live.exists) return;
    const kept = new Set([...mediaNames].map(mediaNameKey));
    const replaced = live
      .list()
      .filter((item) => item instanceof File && !kept.has(mediaNameKey(item.name)))
      .map((item) => item.name);
    deleteLiveMedia(replaced);
  } catch (error) {
    reportError("backup:pruneReplacedMedia", error);
  }
}

/** True when Import needs the explicit destructive confirmation. */
export async function hasLocalContentForImport(): Promise<boolean> {
  const hasEntries = await runDb(async (db) => {
    const row = await db.getFirstAsync<{ count: number }>("SELECT COUNT(*) AS count FROM entries");
    return (row?.count ?? 0) > 0;
  });
  if (hasEntries) return true;
  const media = mediaDirectory();
  return media.exists && media.list().some((item) => item instanceof File && item.exists);
}

/**
 * Validates and stages a backup before it replaces local content in-session.
 */
export async function importBackupArchive(
  fileUri: string,
  options?: ImportBackupOptions
): Promise<ImportBackupResult> {
  const sourceFile = new File(fileUri);
  if (!sourceFile.exists) throw new Error("Selected backup file does not exist.");
  const archiveBytes = sourceFile.info().size ?? 0;
  if (archiveBytes > BACKUP_LIMITS.archiveBytes) {
    throw new Error("Backup file is too large to import.");
  }
  if (options?.signal?.aborted) throw new Error("Import cancelled");
  if (
    options?.expectedArchiveBytes !== undefined &&
    options.expectedArchiveBytes !== archiveBytes
  ) {
    throw new Error(
      "The selected backup file was modified after inspection. Select the file again."
    );
  }

  const existingTimelineBytes = getExistingTimelineDiskBytes();
  const requiredBytes = calculateRequiredImportBytes({
    archiveBytes,
    existingTimelineBytes,
    uncompressedBytes: options?.uncompressedBytes,
    expectedArchiveBytes: options?.expectedArchiveBytes,
  });

  let freeBytes: number | null = null;
  try {
    if (typeof FileSystem.getFreeDiskStorageAsync === "function") {
      freeBytes = await FileSystem.getFreeDiskStorageAsync();
    }
  } catch {
    // Storage check is unsupported on web or test environments.
  }
  if (typeof freeBytes === "number" && freeBytes > 0) {
    if (freeBytes < requiredBytes) {
      throw new Error(
        "Insufficient storage to import backup. OpenLog requires free space for staging."
      );
    }
  }

  await waitForExportGate();
  acquireImportGate();

  const manifestChunks: Uint8Array[] = [];
  const timelineChunks: Uint8Array[] = [];
  let failure: Error | null = null;
  let totalUncompressed = 0;
  let manifestBytes = 0;
  let timelineBytes = 0;
  let mediaCount = 0;
  let stagingDir: Directory | null = null;
  // A cancelled or failed read stops before the member's final chunk, so its handle is closed here.
  const openMediaHandles = new Set<ReturnType<File["open"]>>();
  const paths = new Set<string>();
  const mediaNames = new Set<string>();
  const normalizedMediaNames = new Set<string>();

  try {
    stagingDir = new Directory(Paths.cache, `openlog-import-${Date.now()}`);
    stagingDir.create({ idempotent: true, intermediates: true });
    const stagingMediaDir = new Directory(stagingDir, "incoming-media");
    stagingMediaDir.create({ intermediates: true });

    const unzipper = new Unzip();
    unzipper.register(UnzipInflate);
    unzipper.register(UnzipPassThrough);

    unzipper.onfile = (member) => {
      if (failure) return;
      if (options?.signal?.aborted) {
        failure = new Error("Import cancelled");
        return;
      }

      try {
        validateArchivePath(member.name, paths);
      } catch (err) {
        failure = err instanceof Error ? err : new Error(String(err));
        return;
      }

      paths.add(member.name);
      if (member.originalSize !== undefined && member.originalSize > BACKUP_LIMITS.memberBytes) {
        failure = new Error("Invalid backup file: archive member is too large.");
        return;
      }

      let mediaHandle: ReturnType<File["open"]> | null = null;
      let memberBytes = 0;
      const closeMediaHandle = () => {
        if (!mediaHandle) return;
        openMediaHandles.delete(mediaHandle);
        mediaHandle.close();
        mediaHandle = null;
      };

      try {
        if (member.name.startsWith("media/")) {
          const filename = extractMediaFilename(member.name);
          const filenameKey = mediaNameKey(filename);
          if (normalizedMediaNames.has(filenameKey)) {
            throw new Error("Invalid backup file: duplicate media filename.");
          }
          normalizedMediaNames.add(filenameKey);
          mediaNames.add(filename);
          mediaCount++;
          if (mediaCount > BACKUP_LIMITS.media) {
            throw new Error("Invalid backup file: too many media files.");
          }
          const destination = new File(stagingMediaDir, filename);
          destination.create({ overwrite: true });
          mediaHandle = destination.open(FileMode.WriteOnly);
          openMediaHandles.add(mediaHandle);
        }
      } catch (error) {
        failure = error instanceof Error ? error : new Error(String(error));
        return;
      }

      member.ondata = (error, chunk, final) => {
        if (error) {
          failure = error instanceof Error ? error : new Error(String(error));
          closeMediaHandle();
          return;
        }
        if (options?.signal?.aborted) {
          failure = new Error("Import cancelled");
          closeMediaHandle();
          return;
        }
        memberBytes += chunk.length;
        totalUncompressed += chunk.length;
        if (
          memberBytes > BACKUP_LIMITS.memberBytes ||
          totalUncompressed > BACKUP_LIMITS.uncompressedBytes
        ) {
          failure = new Error("Invalid backup file: archive expands beyond the import limit.");
          closeMediaHandle();
          return;
        }

        try {
          if (member.name === MANIFEST_FILENAME) {
            manifestBytes += chunk.length;
            if (manifestBytes > BACKUP_LIMITS.manifestBytes) {
              throw new Error("Invalid backup manifest: manifest data too large.");
            }
            manifestChunks.push(chunk);
          } else if (member.name === TIMELINE_DATA_FILENAME) {
            timelineBytes += chunk.length;
            if (timelineBytes > BACKUP_LIMITS.timelineDataBytes) {
              throw new Error("Invalid backup data: timeline data too large.");
            }
            timelineChunks.push(chunk);
          } else if (mediaHandle) {
            mediaHandle.writeBytes(chunk);
          }
          if (final) {
            closeMediaHandle();
          }
        } catch (writeError) {
          failure = writeError instanceof Error ? writeError : new Error(String(writeError));
          closeMediaHandle();
        }
      };
      member.start();
    };

    const input = sourceFile.open(FileMode.ReadOnly);
    try {
      const size = input.size ?? 0;
      let read = 0;
      let bytesSinceYield = 0;
      while (read < size) {
        if (failure) throw failure;
        if (options?.signal?.aborted) throw new Error("Import cancelled");
        const chunk = input.readBytes(Math.min(256 * 1024, size - read));
        if (chunk.length === 0) break;
        read += chunk.length;
        options?.onProgress?.(read, size);
        unzipper.push(chunk, read === size);
        bytesSinceYield += chunk.length;
        if (bytesSinceYield >= BACKUP_YIELD_BYTES) {
          bytesSinceYield = 0;
          await new Promise((resolve) => setTimeout(resolve, 0));
        }
      }
    } finally {
      input.close();
    }

    if (failure) throw failure;
    if (!paths.has(MANIFEST_FILENAME) || manifestChunks.length === 0) {
      throw new Error(`Invalid backup file: ${MANIFEST_FILENAME} missing.`);
    }
    if (!paths.has(TIMELINE_DATA_FILENAME) || timelineChunks.length === 0) {
      throw new Error(`Invalid backup file: ${TIMELINE_DATA_FILENAME} missing.`);
    }

    let rawManifest: unknown;
    try {
      rawManifest = JSON.parse(strFromU8(concat(manifestChunks)));
    } catch {
      throw new Error("Invalid backup manifest: malformed JSON.");
    }
    assertBackupManifest(rawManifest);

    let rawTimeline: unknown;
    try {
      rawTimeline = JSON.parse(strFromU8(concat(timelineChunks)));
    } catch {
      throw new Error("Invalid backup data: malformed JSON.");
    }
    assertBackupTimelineData(rawTimeline);

    assertBackupCounts({ manifest: rawManifest, timeline: rawTimeline, mediaCount });
    assertBackupMediaReferences(rawTimeline.entries, mediaNames);
    if (options?.counts) {
      if (
        options.counts.entry !== rawManifest.counts.entry ||
        options.counts.media !== rawManifest.counts.media
      ) {
        throw new Error("Backup counts do not match the expected counts.");
      }
    }
    if (options?.signal?.aborted) throw new Error("Import cancelled");

    // Existing content is only removed after the new rows commit.
    const addedMedia = await publishStagedMedia(stagingMediaDir, mediaNames);
    try {
      await runDb((db) => replaceTimelineData(db, rawTimeline));
    } catch (error) {
      deleteLiveMedia(addedMedia);
      throw error;
    }
    pruneReplacedMedia(mediaNames);
    // Drafts were written against the replaced timeline.
    await discardAllDrafts().catch((error) => reportError("backup:importDrafts", error));

    try {
      notifyStoreReload();
    } catch (error) {
      reportError("backup:importReload", error);
    }

    return { importedCount: rawTimeline.entries.length };
  } catch (error) {
    throw error instanceof Error ? error : new Error("The import could not be completed.");
  } finally {
    for (const handle of openMediaHandles) {
      try {
        handle.close();
      } catch (error) {
        logDevWarning("backup:importMediaHandle", error);
      }
    }
    if (stagingDir?.exists) {
      try {
        stagingDir.delete();
      } catch (error) {
        logDevWarning("backup:importStagingCleanup", error);
      }
    }
    releaseImportGate();
  }
}

import { File, FileMode } from "expo-file-system";
import { strFromU8, Unzip, UnzipInflate, UnzipPassThrough } from "fflate";
import {
  assertBackupManifest,
  BACKUP_LIMITS,
  BACKUP_YIELD_BYTES,
  validateArchivePath,
} from "../utils";
import {
  ARCHIVE_EXTENSION,
  type InspectBackupOptions,
  type InspectBackupResult,
  MANIFEST_FILENAME,
  TIMELINE_DATA_FILENAME,
} from "../utils/types";

function concatChunks(chunks: Uint8Array[]): Uint8Array {
  const length = chunks.reduce((total, chunk) => total + chunk.length, 0);
  const result = new Uint8Array(length);
  let offset = 0;
  for (const chunk of chunks) {
    result.set(chunk, offset);
    offset += chunk.length;
  }
  return result;
}

/**
 * Inspects a backup archive without modifying disk or database.
 * Reads manifest.json only — entries and media files are not loaded into memory.
 * Applies conservative limits, path validation, and duplicate rejection.
 */
export async function inspectBackupArchive(
  fileUri: string,
  options?: InspectBackupOptions
): Promise<InspectBackupResult> {
  const sourceFile = new File(fileUri);
  if (!sourceFile.exists) throw new Error("Selected backup file could not be found.");

  const archiveBytes = sourceFile.info().size ?? 0;
  if (archiveBytes > BACKUP_LIMITS.archiveBytes) {
    throw new Error("Backup file is too large to import.");
  }
  if (options?.signal?.aborted) throw new Error("Inspection cancelled");

  const buffers = { manifestData: null as Uint8Array[] | null };
  let failure: Error | null = null;
  let manifestBytes = 0;
  let totalUncompressed = 0;
  let mediaCount = 0;
  const paths = new Set<string>();

  const unzipper = new Unzip();
  unzipper.register(UnzipInflate);
  unzipper.register(UnzipPassThrough);

  unzipper.onfile = (member) => {
    if (failure) return;
    if (options?.signal?.aborted) {
      failure = new Error("Inspection cancelled");
      return;
    }

    try {
      validateArchivePath(member.name, paths);
    } catch (err) {
      failure = err instanceof Error ? err : new Error(String(err));
      return;
    }
    paths.add(member.name);

    if (member.originalSize !== undefined) {
      if (member.originalSize > BACKUP_LIMITS.memberBytes) {
        failure = new Error("Invalid backup file: archive member is too large.");
        return;
      }
      totalUncompressed += member.originalSize;
      if (totalUncompressed > BACKUP_LIMITS.uncompressedBytes) {
        failure = new Error("Invalid backup file: archive expands beyond the import limit.");
        return;
      }
    }

    if (member.name.startsWith("media/")) {
      mediaCount++;
      if (mediaCount > BACKUP_LIMITS.media) {
        failure = new Error("Invalid backup file: too many media files.");
        return;
      }
    }

    if (member.name === MANIFEST_FILENAME) {
      const chunks: Uint8Array[] = [];
      buffers.manifestData = chunks;
      member.ondata = (err, chunk) => {
        if (err) {
          failure = err instanceof Error ? err : new Error(String(err));
          return;
        }
        if (options?.signal?.aborted) {
          failure = new Error("Inspection cancelled");
          return;
        }
        manifestBytes += chunk.length;
        if (member.originalSize === undefined) totalUncompressed += chunk.length;
        if (manifestBytes > BACKUP_LIMITS.manifestBytes) {
          failure = new Error("Invalid backup manifest: manifest data too large.");
          return;
        }
        if (totalUncompressed > BACKUP_LIMITS.uncompressedBytes) {
          failure = new Error("Invalid backup file: archive expands beyond the import limit.");
          return;
        }
        chunks.push(chunk);
      };
      member.start();
    }
  };

  const CHUNK_SIZE = 256 * 1024;
  const readHandle = sourceFile.open(FileMode.ReadOnly);
  try {
    const fileSize = readHandle.size ?? 0;
    let bytesRead = 0;
    let bytesSinceYield = 0;
    while (bytesRead < fileSize) {
      if (failure) throw failure;
      if (options?.signal?.aborted) throw new Error("Inspection cancelled");
      const chunk = readHandle.readBytes(Math.min(CHUNK_SIZE, fileSize - bytesRead));
      if (chunk.length === 0) break;
      bytesRead += chunk.length;
      try {
        unzipper.push(chunk, bytesRead >= fileSize);
      } catch {
        throw new Error(`Invalid file: Not a valid ${ARCHIVE_EXTENSION} archive.`);
      }
      bytesSinceYield += chunk.length;
      if (bytesSinceYield >= BACKUP_YIELD_BYTES) {
        bytesSinceYield = 0;
        await new Promise((resolve) => setTimeout(resolve, 0));
      }
    }
  } finally {
    readHandle.close();
  }

  if (failure) throw failure;
  if (options?.signal?.aborted) throw new Error("Inspection cancelled");

  if (!paths.has(MANIFEST_FILENAME) || !buffers.manifestData?.length) {
    throw new Error(
      `Invalid file: Not a valid ${ARCHIVE_EXTENSION} archive (${MANIFEST_FILENAME} missing).`
    );
  }
  if (!paths.has(TIMELINE_DATA_FILENAME)) {
    throw new Error(
      `Invalid file: Not a valid ${ARCHIVE_EXTENSION} archive (${TIMELINE_DATA_FILENAME} missing).`
    );
  }

  let data: unknown;
  try {
    data = JSON.parse(strFromU8(concatChunks(buffers.manifestData)));
  } catch {
    throw new Error("Invalid backup manifest: malformed JSON.");
  }
  assertBackupManifest(data);

  return {
    format: data.format,
    version: data.version,
    createdAt: data.createdAt,
    appVersion: data.appVersion,
    counts: {
      entry: data.counts.entry,
      tag: data.counts.tag,
      media: data.counts.media,
    },
    uncompressedBytes: totalUncompressed,
    archiveBytes,
  };
}

import type { Attachment } from "@/shared/types";
import type { BackupTimelineData } from "../utils/types";

export interface ImportDatabase {
  runAsync(source: string, ...params: unknown[]): Promise<unknown>;
  withTransactionAsync(task: () => Promise<void>): Promise<void>;
}

/** Replaces all timeline rows in one transaction; on failure the existing rows remain. */
export async function replaceTimelineData(
  db: ImportDatabase,
  timeline: BackupTimelineData
): Promise<void> {
  await db.withTransactionAsync(async () => {
    await db.runAsync("DELETE FROM entry_tags");
    await db.runAsync("DELETE FROM tags");
    await db.runAsync("DELETE FROM entries");
    await db.runAsync("DELETE FROM settings");

    for (const tag of timeline.tags) {
      await db.runAsync(
        `INSERT INTO tags (id, name, key, color_id, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?)`,
        tag.id,
        tag.name,
        tag.key,
        tag.colorId,
        tag.createdAt,
        tag.updatedAt
      );
    }

    for (const entry of timeline.entries) {
      await db.runAsync(
        `INSERT INTO entries (
           id, created_at, updated_at, text, images, audios, attachments,
           latitude, longitude, location
         ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        entry.id,
        entry.createdAt,
        entry.updatedAt,
        entry.text ?? null,
        entry.images?.length ? JSON.stringify(entry.images) : null,
        entry.audios?.length ? JSON.stringify(entry.audios) : null,
        entry.attachments?.length
          ? JSON.stringify(
              entry.attachments.map(
                ({ uri, name, size, mimeType }): Attachment => ({
                  uri,
                  name,
                  mime: mimeType,
                  size,
                })
              )
            )
          : null,
        entry.location?.latitude ?? null,
        entry.location?.longitude ?? null,
        entry.location?.name ?? null
      );
      for (const tagId of entry.tagIds ?? []) {
        await db.runAsync(
          "INSERT INTO entry_tags (entry_id, tag_id) VALUES (?, ?)",
          entry.id,
          tagId
        );
      }
    }

    if (timeline.settings) {
      for (const [key, value] of Object.entries(timeline.settings)) {
        await db.runAsync("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", key, value);
      }
    }
    await db.runAsync("INSERT INTO entries_fts(entries_fts) VALUES ('rebuild')");
  });
}

import { getDocumentAsync } from "expo-document-picker";
import { Directory, File } from "expo-file-system";

import { logDevWarning } from "@/shared/utils/devLog";

import { ARCHIVE_EXTENSION } from "./types";

/**
 * Prompts user with the system file picker to select a backup archive.
 */
export async function pickBackupArchiveFile(): Promise<string | null> {
  const result = await getDocumentAsync({
    type: ["*/*", "application/octet-stream", "application/zip"],
    copyToCacheDirectory: true,
  });

  if (result.canceled || !result.assets?.[0]?.uri) return null;

  const asset = result.assets[0];
  const name = (asset.name || asset.uri).toLowerCase();
  if (!name.endsWith(ARCHIVE_EXTENSION) && !name.endsWith(`${ARCHIVE_EXTENSION}.zip`)) {
    throw new Error(`Select a valid ${ARCHIVE_EXTENSION} backup file.`);
  }

  return asset.uri;
}

/**
 * Prompts user to pick a folder upfront for backup storage.
 * Returns null if cancelled. Throws error if unsupported or picker fails.
 */
export async function pickBackupDestinationDirectory(): Promise<Directory | null> {
  try {
    const targetDir = await Directory.pickDirectoryAsync();
    if (!targetDir?.uri) return null;
    return targetDir;
  } catch (pickerErr) {
    if (
      pickerErr instanceof Error &&
      (/cancel/i.test(pickerErr.message) || /cancel/i.test(pickerErr.name))
    ) {
      return null;
    }
    throw pickerErr;
  }
}

/**
 * Copies a completed backup archive to a destination directory using native streaming,
 * then removes the temporary archive from cache.
 */
export async function copyBackupToDirectory(
  fileUri: string,
  filename: string,
  targetDir: Directory
): Promise<void> {
  const sourceFile = new File(fileUri);
  if (!sourceFile.exists) throw new Error("Backup file could not be found.");
  if (sourceFile.name !== filename) sourceFile.rename(filename);
  await sourceFile.copy(targetDir, { overwrite: true });
  try {
    sourceFile.delete();
  } catch (err) {
    logDevWarning("copyBackupToDirectory:deleteSource", err);
  }
}

export const ARCHIVE_FORMAT = "openlog-backup" as const;
export const ARCHIVE_SCHEMA_VERSION = 1;
export const ARCHIVE_EXTENSION = ".openlog";
export const MANIFEST_FILENAME = "manifest.json" as const;
export const TIMELINE_DATA_FILENAME = "timeline.json" as const;

export interface BackupArchiveCounts {
  entry: number;
  tag: number;
  media: number;
}

export type ArchiveCounts = {
  entry: number;
  tag?: number;
  media: number;
};

export interface BackupManifest {
  format: typeof ARCHIVE_FORMAT;
  version: number;
  createdAt: number;
  appVersion: string;
  counts: BackupArchiveCounts;
}

export interface BackupTag {
  id: string;
  name: string;
  key: string;
  colorId: string;
  createdAt: number;
  updatedAt: number;
}

export interface BackupAttachment {
  uri: string;
  name: string;
  size?: number;
  mimeType?: string;
}

export interface BackupLocation {
  latitude: number;
  longitude: number;
  name?: string;
}

export interface BackupEntry {
  id: string;
  createdAt: number;
  updatedAt: number;
  text?: string | null;
  images?: string[];
  audios?: string[];
  attachments?: BackupAttachment[];
  tagIds?: string[];
  location?: BackupLocation | null;
}

export interface BackupTimelineData {
  tags: BackupTag[];
  entries: BackupEntry[];
  preferences?: Record<string, unknown>;
  settings?: Record<string, string>;
}

export interface InspectBackupResult {
  format: string;
  version: number;
  createdAt: number;
  appVersion: string;
  counts: { entry: number; tag?: number; media: number };
  uncompressedBytes?: number;
  archiveBytes?: number;
}

export interface InspectBackupOptions {
  signal?: AbortSignal;
}

export interface ExportBackupResult {
  fileUri: string;
  filename: string;
  counts: { entry: number; tag: number; media: number };
  byteSize: number;
}

export type ExportBackupPhase = "entries" | "media";

export interface ExportBackupOptions {
  signal?: AbortSignal;
  onProgress?: (processed: number, total: number, phase: ExportBackupPhase) => void;
}

export interface ImportBackupResult {
  importedCount: number;
}

export interface ImportBackupOptions {
  signal?: AbortSignal;
  onProgress?: (processedBytes: number, totalBytes: number) => void;
  counts?: { entry: number; tag?: number; media: number };
  uncompressedBytes?: number;
  expectedArchiveBytes?: number;
}

import { useSyncExternalStore } from "react";

export interface BackupStatus {
  isExporting: boolean;
  isImporting: boolean;
}

let activeExportController: AbortController | null = null;
let activeImportController: AbortController | null = null;
const backupStatusListeners = new Set<() => void>();
let cachedStatus: BackupStatus = { isExporting: false, isImporting: false };

function notifyBackupStatusChange() {
  for (const listener of backupStatusListeners) {
    listener();
  }
}

export function getBackupStatus(): BackupStatus {
  const isExporting = activeExportController !== null;
  const isImporting = activeImportController !== null;
  if (cachedStatus.isExporting !== isExporting || cachedStatus.isImporting !== isImporting) {
    cachedStatus = { isExporting, isImporting };
  }
  return cachedStatus;
}

export function subscribeBackupStatus(listener: () => void): () => void {
  backupStatusListeners.add(listener);
  return () => {
    backupStatusListeners.delete(listener);
  };
}

/**
 * Hook to reactively observe if a backup export or import operation is in flight.
 */
export function useBackupStatus(): BackupStatus {
  return useSyncExternalStore(subscribeBackupStatus, getBackupStatus);
}

export function setExportController(controller: AbortController | null): void {
  activeExportController = controller;
  notifyBackupStatusChange();
}

export function setImportController(controller: AbortController | null): void {
  activeImportController = controller;
  notifyBackupStatusChange();
}

export function cancelActiveBackup(): boolean {
  if (activeExportController) {
    activeExportController.abort();
    activeExportController = null;
    notifyBackupStatusChange();
    return true;
  }
  return false;
}

export function cancelActiveImport(): boolean {
  if (activeImportController) {
    activeImportController.abort();
    activeImportController = null;
    notifyBackupStatusChange();
    return true;
  }
  return false;
}

import { FONTSOURCE_VERSIONS } from "./catalog.ts";
import type { FontName, FontSource } from "./types";

/**
 * Converts a canonical font family name into a package slug for CDN lookup.
 * E.g. "Source Sans 3" -> "source-sans-3", "Plus Jakarta Sans" -> "plus-jakarta-sans".
 */
export function fontNameToSlug(fontName: string): string {
  return fontName
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

/**
 * Resolves a font family name to its remote downloadable TTF source.
 */
export function resolveFontSource(fontName: FontName): FontSource {
  const version = FONTSOURCE_VERSIONS.get(fontName);
  if (!version) throw new Error(`No pinned font source for "${fontName}"`);
  const slug = fontNameToSlug(fontName);
  const url = `https://cdn.jsdelivr.net/fontsource/fonts/${slug}@${version}/latin-400-normal.ttf`;
  return {
    family: fontName,
    url,
  };
}

import { Directory, File, Paths } from "expo-file-system";

import { logDevWarning } from "@/shared/utils/devLog";
import { fontNameToSlug } from "./resolver";
import type { FontName } from "./types";

function fontsDirectory(): Directory {
  return new Directory(Paths.document, "fonts");
}

function ensureDirectory(): Directory {
  const dir = fontsDirectory();
  dir.create({ idempotent: true, intermediates: true });
  return dir;
}

export function getFontFile(fontName: FontName): File {
  const dir = fontsDirectory();
  const filename = `${fontNameToSlug(fontName)}.ttf`;
  return new File(dir, filename);
}

export const fontCache = {
  /**
   * Checks whether the font file exists in local storage.
   */
  has(fontName: FontName): boolean {
    try {
      const file = getFontFile(fontName);
      return file.exists;
    } catch {
      return false;
    }
  },

  /**
   * Returns the File object for the given font name, or null if it does not exist.
   */
  get(fontName: FontName): File | null {
    try {
      const file = getFontFile(fontName);
      return file.exists ? file : null;
    } catch {
      return null;
    }
  },

  /**
   * Downloads a remote font file and saves it into the local cache.
   */
  async save(fontName: FontName, url: string): Promise<File> {
    ensureDirectory();
    const dest = getFontFile(fontName);
    return File.downloadFileAsync(url, dest, { idempotent: true });
  },

  /**
   * Deletes a cached font file.
   */
  async remove(fontName: FontName): Promise<void> {
    try {
      const file = getFontFile(fontName);
      if (file.exists) {
        file.delete();
      }
    } catch (error) {
      logDevWarning("fontCache:remove", error);
    }
  },

  /**
   * Clears all cached font files.
   */
  async clear(): Promise<void> {
    try {
      const dir = fontsDirectory();
      if (dir.exists) {
        dir.delete();
        ensureDirectory();
      }
    } catch (error) {
      logDevWarning("fontCache:clear", error);
    }
  },
};

import * as Font from "expo-font";

import { logDevWarning } from "@/shared/utils/devLog";
import { fontCache, getFontFile } from "./cache";
import { DEFAULT_FONT, getFonts, hasFont } from "./catalog";
import { resolveFontSource } from "./resolver";
import type { FontLoadResult, FontName } from "./types";

class FontManager {
  private inFlightLoads = new Map<string, Promise<FontLoadResult>>();

  /**
   * Returns all available font family names in the catalog.
   */
  getFonts(): readonly FontName[] {
    return getFonts();
  }

  /**
   * Checks whether a font name is present in the catalog.
   */
  hasFont(fontName: string): boolean {
    return hasFont(fontName);
  }

  /**
   * The default bootstrap font, bundled with the app.
   */
  getDefaultFont(): FontName {
    return DEFAULT_FONT;
  }

  /**
   * Synchronously checks if a font is already loaded and ready for rendering.
   * Default font ("Source Sans 3") is always considered loaded via app bundle.
   */
  isLoaded(fontName: FontName): boolean {
    if (fontName === DEFAULT_FONT) {
      return true;
    }
    return Font.isLoaded(fontName);
  }

  /**
   * Checks whether the font file is downloaded and cached locally.
   */
  isCached(fontName: FontName): boolean {
    if (fontName === DEFAULT_FONT) {
      return true;
    }
    return fontCache.has(fontName);
  }

  /**
   * Loads a font by canonical family name.
   *
   * Coordinates:
   *   1. Deduplication of concurrent in-flight requests.
   *   2. Cache lookup.
   *   3. On-demand downloading.
   *   4. expo-font registration.
   *   5. Auto-recovery from corrupt cache files.
   *   6. Fallback to Source Sans 3 on failure.
   */
  async load(fontName: FontName): Promise<FontLoadResult> {
    // 1. Validation against catalog
    if (!hasFont(fontName)) {
      logDevWarning("fontManager:load", `Font "${fontName}" does not exist in catalog.`);
      return { success: false, fontFamily: DEFAULT_FONT };
    }

    // 2. Default font is bundled
    if (fontName === DEFAULT_FONT) {
      return { success: true, fontFamily: DEFAULT_FONT };
    }

    // 3. Already loaded in React Native font system
    if (Font.isLoaded(fontName)) {
      return { success: true, fontFamily: fontName };
    }

    // 4. Deduplicate concurrent in-flight requests
    const existingPromise = this.inFlightLoads.get(fontName);
    if (existingPromise) {
      return existingPromise;
    }

    const loadPromise = this.executeLoad(fontName);
    this.inFlightLoads.set(fontName, loadPromise);

    try {
      return await loadPromise;
    } finally {
      this.inFlightLoads.delete(fontName);
    }
  }

  /**
   * Preloads a font in the background without blocking.
   */
  async preload(fontName: FontName): Promise<FontLoadResult> {
    return this.load(fontName);
  }

  /**
   * Removes a font file from the local cache.
   */
  async remove(fontName: FontName): Promise<void> {
    await fontCache.remove(fontName);
  }

  /**
   * Clears the entire font cache.
   */
  async clearCache(): Promise<void> {
    await fontCache.clear();
  }

  private async executeLoad(fontName: FontName): Promise<FontLoadResult> {
    // If cached, try loading the cached file first
    if (fontCache.has(fontName)) {
      try {
        const file = getFontFile(fontName);
        await Font.loadAsync({ [fontName]: file.uri });
        return { success: true, fontFamily: fontName };
      } catch (error) {
        logDevWarning(`fontManager:cachedLoadFailed (${fontName}) - invalidating cache`, error);
        // Invalidate corrupt cache file and attempt fresh download below
        await fontCache.remove(fontName);
      }
    }

    // Download from remote font source
    try {
      const source = resolveFontSource(fontName);
      const savedFile = await fontCache.save(fontName, source.url);
      await Font.loadAsync({ [fontName]: savedFile.uri });
      return { success: true, fontFamily: fontName };
    } catch (error) {
      logDevWarning(`fontManager:downloadOrLoadFailed (${fontName})`, error);
      return { success: false, fontFamily: DEFAULT_FONT };
    }
  }
}

export const fontManager = new FontManager();

import {
  ARCHIVE_FORMAT,
  ARCHIVE_SCHEMA_VERSION,
  type BackupManifest,
  type BackupTimelineData,
  MANIFEST_FILENAME,
  TIMELINE_DATA_FILENAME,
} from "./types.ts";

/** Rejects backups whose entries refer to media that was not actually archived. */
export function assertBackupMediaReferences(
  entries: BackupTimelineData["entries"],
  mediaNames: ReadonlySet<string>
): void {
  for (const entry of entries) {
    const references = [
      ...(entry.images ?? []),
      ...(entry.audios ?? []),
      ...(entry.attachments?.map((attachment) => attachment.uri) ?? []),
    ];
    for (const filename of references) {
      if (!mediaNames.has(filename)) {
        throw new Error(`Invalid backup file: media file ${filename} is missing.`);
      }
    }
  }
}

export interface BackupCountsInput {
  manifest: BackupManifest;
  timeline: BackupTimelineData;
  mediaCount: number;
}

/** Rejects archives whose contents disagree with the counts their manifest declares. */
export function assertBackupCounts({ manifest, timeline, mediaCount }: BackupCountsInput): void {
  if (timeline.entries.length !== manifest.counts.entry) {
    throw new Error(
      `Backup entry count mismatch (${timeline.entries.length} entries, manifest specifies ${manifest.counts.entry}).`
    );
  }
  if (timeline.tags.length !== manifest.counts.tag) {
    throw new Error(
      `Backup tag count mismatch (${timeline.tags.length} tags, manifest specifies ${manifest.counts.tag}).`
    );
  }
  if (mediaCount !== manifest.counts.media) {
    throw new Error(
      `Backup media count mismatch (${mediaCount} media files, manifest specifies ${manifest.counts.media}).`
    );
  }
}

function isNonNegativeInteger(value: unknown): boolean {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

/** A restorable media reference: a non-empty bare filename with no path or traversal. */
function isBareFilename(value: unknown): value is string {
  return (
    typeof value === "string" &&
    value.length > 0 &&
    !value.includes("/") &&
    !value.includes("\\") &&
    value !== "." &&
    value !== ".."
  );
}

/** Validates the backup manifest metadata. */
export function assertBackupManifest(data: unknown): asserts data is BackupManifest {
  if (!data || typeof data !== "object") {
    throw new Error("Invalid backup manifest: not an object.");
  }
  const obj = data as Record<string, unknown>;
  if (obj.format !== ARCHIVE_FORMAT) {
    throw new Error(`Invalid backup format: ${String(obj.format)}`);
  }
  if (typeof obj.version !== "number" || !Number.isInteger(obj.version) || obj.version < 1) {
    throw new Error(`Invalid backup file: unsupported archive version (${String(obj.version)}).`);
  }
  if (obj.version > ARCHIVE_SCHEMA_VERSION) {
    throw new Error(`Unsupported backup version (${obj.version}). Update OpenLog.`);
  }
  if (typeof obj.createdAt !== "number" || !Number.isFinite(obj.createdAt)) {
    throw new Error("Invalid backup manifest: createdAt is missing or invalid.");
  }
  if (typeof obj.appVersion !== "string" || !obj.appVersion) {
    throw new Error("Invalid backup manifest: appVersion is missing.");
  }
  if (!obj.counts || typeof obj.counts !== "object") {
    throw new Error("Invalid backup manifest: counts is missing.");
  }
  const counts = obj.counts as Record<string, unknown>;
  if (
    !isNonNegativeInteger(counts.entry) ||
    !isNonNegativeInteger(counts.tag) ||
    !isNonNegativeInteger(counts.media)
  ) {
    throw new Error("Invalid backup manifest: counts must be non-negative integers.");
  }
}

/** Validates timeline data, including the uniqueness and reference rules the database enforces. */
export function assertBackupTimelineData(data: unknown): asserts data is BackupTimelineData {
  if (!data || typeof data !== "object") {
    throw new Error("Invalid backup timeline: not an object.");
  }
  const obj = data as Record<string, unknown>;

  if (!Array.isArray(obj.tags)) {
    throw new Error("Invalid backup timeline: tags must be an array.");
  }
  const tagIds = new Set<string>();
  const tagKeys = new Set<string>();
  for (const tag of obj.tags) {
    if (!tag || typeof tag !== "object") {
      throw new Error("Invalid backup tag: malformed item.");
    }
    const t = tag as Record<string, unknown>;
    if (typeof t.id !== "string" || !t.id) throw new Error("Invalid backup tag: missing id.");
    if (typeof t.name !== "string" || !t.name) throw new Error("Invalid backup tag: missing name.");
    if (typeof t.key !== "string") throw new Error("Invalid backup tag: key is required.");
    if (typeof t.colorId !== "string" || !t.colorId)
      throw new Error("Invalid backup tag: missing colorId.");
    if (typeof t.createdAt !== "number" || !Number.isFinite(t.createdAt)) {
      throw new Error("Invalid backup tag: createdAt is required.");
    }
    if (typeof t.updatedAt !== "number" || !Number.isFinite(t.updatedAt)) {
      throw new Error("Invalid backup tag: updatedAt is required.");
    }
    if (tagIds.has(t.id)) throw new Error("Invalid backup tag: duplicate id.");
    if (tagKeys.has(t.key)) throw new Error("Invalid backup tag: duplicate name.");
    tagIds.add(t.id);
    tagKeys.add(t.key);
  }

  if (!Array.isArray(obj.entries)) {
    throw new Error("Invalid backup timeline: entries must be an array.");
  }
  const entryIds = new Set<string>();
  for (const entry of obj.entries) {
    if (!entry || typeof entry !== "object") {
      throw new Error("Invalid backup entry: malformed item.");
    }
    const e = entry as Record<string, unknown>;
    if (typeof e.id !== "string" || !e.id) throw new Error("Invalid backup entry: missing id.");
    if (entryIds.has(e.id)) throw new Error("Invalid backup entry: duplicate id.");
    entryIds.add(e.id);
    if (typeof e.createdAt !== "number" || !Number.isFinite(e.createdAt)) {
      throw new Error("Invalid backup entry: createdAt is required.");
    }
    if (typeof e.updatedAt !== "number" || !Number.isFinite(e.updatedAt)) {
      throw new Error("Invalid backup entry: updatedAt is required.");
    }
    if (e.text !== undefined && e.text !== null && typeof e.text !== "string") {
      throw new Error("Invalid backup entry: text must be a string or null.");
    }
    if (e.images !== undefined && (!Array.isArray(e.images) || !e.images.every(isBareFilename))) {
      throw new Error("Invalid backup entry: images must be media filenames.");
    }
    if (e.audios !== undefined && (!Array.isArray(e.audios) || !e.audios.every(isBareFilename))) {
      throw new Error("Invalid backup entry: audios must be media filenames.");
    }
    if (e.attachments !== undefined) {
      if (!Array.isArray(e.attachments)) {
        throw new Error("Invalid backup entry: attachments must be an array.");
      }
      for (const item of e.attachments as unknown[]) {
        const attachment =
          item && typeof item === "object" ? (item as Record<string, unknown>) : null;
        if (!attachment || !isBareFilename(attachment.uri)) {
          throw new Error("Invalid backup entry: attachment uris must be media filenames.");
        }
        if (typeof attachment.name !== "string") {
          throw new Error("Invalid backup entry: attachment names must be strings.");
        }
        if (attachment.mimeType !== undefined && typeof attachment.mimeType !== "string") {
          throw new Error("Invalid backup entry: attachment types must be strings.");
        }
      }
    }
    if (e.tagIds !== undefined) {
      if (!Array.isArray(e.tagIds)) {
        throw new Error("Invalid backup entry: tagIds must be an array.");
      }
      const entryTagIds = new Set<string>();
      for (const tagId of e.tagIds) {
        if (typeof tagId !== "string" || !tagIds.has(tagId)) {
          throw new Error("Invalid backup entry: tagIds must reference backup tags.");
        }
        if (entryTagIds.has(tagId)) throw new Error("Invalid backup entry: duplicate tag.");
        entryTagIds.add(tagId);
      }
    }
    if (e.location !== undefined && e.location !== null) {
      if (typeof e.location !== "object") {
        throw new Error("Invalid backup entry: location must be an object or null.");
      }
      const loc = e.location as Record<string, unknown>;
      if (typeof loc.latitude !== "number" || typeof loc.longitude !== "number") {
        throw new Error("Invalid backup entry: location coordinates must be numbers.");
      }
      if (loc.name !== undefined && loc.name !== null && typeof loc.name !== "string") {
        throw new Error("Invalid backup entry: location name must be a string.");
      }
    }
  }

  if (obj.settings !== undefined) {
    if (typeof obj.settings !== "object" || obj.settings === null || Array.isArray(obj.settings)) {
      throw new Error("Invalid backup timeline: settings must be an object.");
    }
    if (!Object.values(obj.settings).every((value) => typeof value === "string")) {
      throw new Error("Invalid backup timeline: settings values must be strings.");
    }
  }
  if (
    obj.preferences !== undefined &&
    (typeof obj.preferences !== "object" || obj.preferences === null)
  ) {
    throw new Error("Invalid backup timeline: preferences must be an object.");
  }
}

export const BACKUP_LIMITS = {
  archiveBytes: 512 * 1024 * 1024,
  uncompressedBytes: 2 * 1024 * 1024 * 1024,
  memberBytes: 256 * 1024 * 1024,
  timelineDataBytes: 64 * 1024 * 1024,
  manifestBytes: 64 * 1024 * 1024,
  media: 100_000,
} as const;

/** Archive reads pause for the UI after this many bytes so progress renders and Cancel can land. */
export const BACKUP_YIELD_BYTES = 2 * 1024 * 1024;

export const IMPORT_SAFETY_BUFFER_BYTES = 50 * 1024 * 1024;

export interface ExportSizeLimitsInput {
  manifestBytes: number;
  timelineBytes: number;
  mediaBytes: readonly number[];
}

/** Keeps successful exports within the limits enforced by import. */
export function assertBackupExportSizeLimits({
  manifestBytes,
  timelineBytes,
  mediaBytes,
}: ExportSizeLimitsInput): void {
  if (manifestBytes > BACKUP_LIMITS.manifestBytes) {
    throw new Error("Backup manifest is too large to import.");
  }
  if (timelineBytes > BACKUP_LIMITS.timelineDataBytes) {
    throw new Error("Backup data is too large to import.");
  }
  if (mediaBytes.length > BACKUP_LIMITS.media) {
    throw new Error("Backup contains too many media files to import.");
  }
  const total = manifestBytes + timelineBytes + mediaBytes.reduce((sum, bytes) => sum + bytes, 0);
  if (total > BACKUP_LIMITS.uncompressedBytes) {
    throw new Error("Backup expands beyond the import limit.");
  }
  if (mediaBytes.some((bytes) => bytes > BACKUP_LIMITS.memberBytes)) {
    throw new Error("A media file is too large to include in a restorable backup.");
  }
}

export function assertBackupArchiveSize(bytes: number): void {
  if (bytes > BACKUP_LIMITS.archiveBytes) {
    throw new Error("Backup is too large to import.");
  }
}

export interface StoragePreflightParams {
  archiveBytes: number;
  existingTimelineBytes: number;
  uncompressedBytes?: number;
  expectedArchiveBytes?: number;
  safetyBufferBytes?: number;
}

/**
 * Calculates the required free disk storage before an import begins.
 * Uses exact uncompressedBytes when the archive size matches expectedArchiveBytes;
 * otherwise conservatively reserves the full allowed expansion capacity up to BACKUP_LIMITS.uncompressedBytes.
 */
export function calculateRequiredImportBytes({
  archiveBytes,
  existingTimelineBytes,
  uncompressedBytes,
  expectedArchiveBytes,
  safetyBufferBytes = IMPORT_SAFETY_BUFFER_BYTES,
}: StoragePreflightParams): number {
  const isSizeUnchanged =
    expectedArchiveBytes !== undefined && expectedArchiveBytes === archiveBytes;
  const estimatedStagingBytes =
    uncompressedBytes !== undefined && uncompressedBytes > 0 && isSizeUnchanged
      ? Math.min(uncompressedBytes, BACKUP_LIMITS.uncompressedBytes)
      : Math.min(Math.max(archiveBytes * 4, 10 * 1024 * 1024), BACKUP_LIMITS.uncompressedBytes);

  return archiveBytes + estimatedStagingBytes + existingTimelineBytes + safetyBufferBytes;
}

/**
 * Validates that an archive path adheres to the expected format:
 * - "manifest.json"
 * - "timeline.json"
 * - "media/<filename>" (non-empty, single segment, no traversal or backslashes)
 * Rejects path traversal, duplicate paths, and unexpected paths.
 */
export function validateArchivePath(name: string, seenPaths?: Set<string>): void {
  if (name.startsWith("/") || name.startsWith("\\") || name.includes("..") || name.includes("\\")) {
    throw new Error("Invalid backup file: unexpected archive path.");
  }
  if (seenPaths?.has(name)) {
    if (name === MANIFEST_FILENAME) {
      throw new Error("Invalid backup file: duplicate manifest.");
    }
    if (name === TIMELINE_DATA_FILENAME) {
      throw new Error("Invalid backup file: duplicate timeline data.");
    }
    throw new Error("Invalid backup file: duplicate archive path.");
  }
  if (name === MANIFEST_FILENAME || name === TIMELINE_DATA_FILENAME) {
    return;
  }
  if (name.startsWith("media/")) {
    const filename = name.slice("media/".length);
    if (
      filename.length === 0 ||
      filename.includes("/") ||
      filename === "." ||
      filename === ".." ||
      filename.includes("\\")
    ) {
      throw new Error("Invalid backup file: unexpected archive path.");
    }
    return;
  }
  throw new Error("Invalid backup file: unexpected archive path.");
}

export function extractMediaFilename(path: string): string {
  validateArchivePath(path);
  if (!path.startsWith("media/")) {
    throw new Error("Invalid media path in backup archive.");
  }
  return path.slice("media/".length);
}

let activeExports = 0;
let exportsDone: Promise<void> | null = null;
let resolveExportsDone: (() => void) | null = null;
let gateGeneration = 0;

/** Exports may overlap, so the gate stays closed until the last one releases it. */
export function acquireExportGate(): void {
  if (resolveImportGate) throw new Error("An import is in progress.");
  gateGeneration += 1;
  activeExports += 1;
  exportsDone ??= new Promise<void>((resolve) => {
    resolveExportsDone = resolve;
  });
}

export function releaseExportGate(): void {
  if (activeExports === 0) return;
  activeExports -= 1;
  if (activeExports > 0) return;
  resolveExportsDone?.();
  resolveExportsDone = null;
  exportsDone = null;
}

export async function waitForExportGate(): Promise<void> {
  while (exportsDone) await exportsDone;
}

let activeImportGatePromise: Promise<void> | null = null;
let resolveImportGate: (() => void) | null = null;

export function acquireImportGate(): void {
  if (resolveImportGate) throw new Error("An import is already in progress.");
  if (activeExports > 0) throw new Error("An export is in progress.");
  gateGeneration += 1;
  activeImportGatePromise = new Promise<void>((resolve) => {
    resolveImportGate = resolve;
  });
}

export function releaseImportGate(): void {
  resolveImportGate?.();
  resolveImportGate = null;
  activeImportGatePromise = null;
}

export async function waitForImportGate(): Promise<void> {
  while (activeImportGatePromise) await activeImportGatePromise;
}

/** Changes whenever an export or import acquires its gate. */
export function backupGateGeneration(): number {
  return gateGeneration;
}

/**
 * Resolves once neither gate is held, with the generation at that moment. A caller whose
 * generation still matches later knows no export or import has started since.
 */
export async function waitForBackupGates(): Promise<number> {
  for (;;) {
    if (exportsDone) await exportsDone;
    else if (activeImportGatePromise) await activeImportGatePromise;
    else return gateGeneration;
  }
}

import type { FontName } from "./types";

export const DEFAULT_FONT: FontName = "Source Sans 3";

/**
 * Downloadable fonts in display order, each with its exact Fontsource package version so
 * every new download gets the same files. Cached fonts are keyed by slug only, so raising
 * a version does not refresh existing caches. The default font is bundled with the app.
 */
export const FONTSOURCE_VERSIONS: ReadonlyMap<FontName, string> = new Map([
  // Modern Sans
  ["Inter", "5.3.0"],
  ["Plus Jakarta Sans", "5.3.0"],
  ["Work Sans", "5.3.0"],

  // Editorial Serif
  ["Source Serif 4", "5.3.1"],
  ["Merriweather", "5.3.0"],
  ["EB Garamond", "5.3.0"],
  ["Fraunces", "5.3.0"],

  // Monospaced
  ["JetBrains Mono", "5.3.0"],
  ["IBM Plex Mono", "5.3.0"],
]);

/** Font catalog of canonical family names; fonts are downloaded lazily on demand. */
export const FONTS: readonly FontName[] = [DEFAULT_FONT, ...FONTSOURCE_VERSIONS.keys()];

const FONT_SET = new Set<string>(FONTS);

export function hasFont(fontName: string): boolean {
  return FONT_SET.has(fontName);
}

export function getFonts(): readonly FontName[] {
  return FONTS;
}

