import React from 'react';
import { StyleProp, ViewStyle } from 'react-native';
import { PostHog, PostHogOptions } from './posthog-rn';
import { PostHogAutocaptureOptions } from './types';
/**
 * Props for the PostHogProvider component.
 *
 * @public
 */
export interface PostHogProviderProps {
    /** The child components to render within the PostHog context */
    children: React.ReactNode;
    /** PostHog configuration options */
    options?: PostHogOptions;
    /** Your PostHog API key */
    apiKey?: string;
    /** An existing PostHog client instance */
    client?: PostHog;
    /**
     * Autocapture configuration - can be a boolean or detailed options.
     *
     * When not set, the default behavior is:
     * - `captureScreens`: true
     * - `captureTouches`: false
     * - `captureAppLifecycleEvents`: true
     *
     * Set to `true` to enable all autocapture features (including touches).
     * Set to `false` to disable all autocapture features.
     */
    autocapture?: boolean | PostHogAutocaptureOptions;
    /**
     * Enable debug mode for additional logging
     *
     * @default false
     */
    debug?: boolean;
    /** Custom styles for the provider wrapper View */
    style?: StyleProp<ViewStyle>;
}
/**
 * PostHogProvider is a React component that provides PostHog functionality to your React Native app. You can find all configuration options in the [React Native SDK docs](https://posthog.com/docs/libraries/react-native#configuration-options).
 *
 * Autocapturing navigation requires further configuration. See the [React Native SDK navigation docs](https://posthog.com/docs/libraries/react-native#capturing-screen-views)
 * for more information about autocapturing navigation.
 *
 * This is the recommended way to set up PostHog for React Native. This utilizes the Context API to pass the PostHog client around, enable autocapture.
 *
 * {@label Initialization}
 *
 * @example
 * ```jsx
 * // Add to App.(js|ts)
 * import { usePostHog, PostHogProvider } from 'posthog-react-native'
 *
 * export function MyApp() {
 *     return (
 *         <PostHogProvider apiKey="<ph_project_api_key>" options={{
 *             host: '<ph_client_api_host>',
 *         }}>
 *             <MyComponent />
 *         </PostHogProvider>
 *     )
 * }
 *
 * // And access the PostHog client via the usePostHog hook
 * import { usePostHog } from 'posthog-react-native'
 *
 * const MyComponent = () => {
 *     const posthog = usePostHog()
 *
 *     useEffect(() => {
 *         posthog.capture("event_name")
 *     }, [posthog])
 * }
 *
 * ```
 *
 * @example
 * ```jsx
 * // Using with existing client
 * import { PostHog } from 'posthog-react-native'
 *
 * const posthog = new PostHog('<ph_project_api_key>', {
 *     host: '<ph_client_api_host>'
 * })
 *
 * export function MyApp() {
 *     return (
 *         <PostHogProvider client={posthog}>
 *             <MyComponent />
 *         </PostHogProvider>
 *     )
 * }
 * ```
 *
 * @public
 *
 * @param props - The PostHogProvider props
 */
export declare const PostHogProvider: ({ children, client, options, apiKey, autocapture, style, debug, }: PostHogProviderProps) => JSX.Element | null;

import * as Application from "expo-application";
import Constants from "expo-constants";

/**
 * Native application version (e.g. "1.0.0"), queried directly from the
 * compiled binary (iOS CFBundleShortVersionString / Android versionName),
 * falling back to static `app.json` expoConfig. Null when unavailable.
 */
export const APP_VERSION: string | null =
  Application.nativeApplicationVersion ?? Constants.expoConfig?.version ?? null;

/**
 * Native build number (iOS CFBundleVersion / Android versionCode).
 */
export const BUILD_NUMBER: string | null = Application.nativeBuildVersion ?? null;

/**
 * Native application ID / bundle identifier.
 */
export const APPLICATION_ID: string | null = Application.applicationId ?? null;

/**
 * Formats byte count into a human-readable string (e.g. "25.4 MB").
 */
export function formatBytes(bytes: number): string {
  if (bytes <= 0) return "0 B";
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`;
}

export * from "./appLockStore";
export * from "./auth";
export * from "./useAppLock";

import { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
import { AppState, type AppStateStatus } from "react-native";

import { analytics } from "@/config/analytics";
import { authenticate, getEnrolledAuthLevel } from "./auth";

const UNLOCK_REASON = "Unlock your entries";
const BACKGROUND_LOCK_THRESHOLD_MS = 60 * 1000; // 1 minute in background before re-locking

const AppLockedContext = createContext(false);

export const AppLockedProvider = AppLockedContext.Provider;

/**
 * True while the app is locked. Native modals draw in their own window above the
 * lock screen, so they must stop rendering while this holds. They deliberately
 * stay up through brief inactive states: dismissing a modal there interrupts
 * anything it presented (share sheet, permission alert) and resets its content.
 */
export function useAppLocked(): boolean {
  return useContext(AppLockedContext);
}

/**
 * Owns the app-lock gate:
 *   - opens locked and prompts while the lock is enabled
 *   - hides content whenever the app is not active; this renders from JS, so
 *     the OS may take its app-switcher snapshot before the cover lands
 *   - re-locks after > 60 seconds in background
 *   - opens directly when the device has no unlock method left, so the user
 *     is never trapped outside their data (the enabled preference is kept and
 *     the lock resumes once a screen lock exists again)
 */
export function useAppLock(enabled: boolean) {
  const [locked, setLocked] = useState(enabled);
  const [prompting, setPrompting] = useState(false);
  const [appState, setAppState] = useState<AppStateStatus>(AppState.currentState);

  const lockedRef = useRef(locked);
  const promptingRef = useRef(false);
  const enabledRef = useRef(enabled);
  const backgroundTimeRef = useRef<number | null>(null);

  lockedRef.current = locked;
  enabledRef.current = enabled;

  const unlock = useCallback(async () => {
    if (promptingRef.current || !lockedRef.current) return;

    promptingRef.current = true;
    setPrompting(true);

    try {
      if ((await getEnrolledAuthLevel()) === "none") {
        // Nothing on the device can verify the owner; prompting could never
        // succeed and reinstalling would destroy the local timeline.
        analytics.capture("app_lock_bypassed");
        setLocked(false);
        return;
      }

      if (await authenticate(UNLOCK_REASON)) {
        setLocked(false);
      }
    } finally {
      promptingRef.current = false;
      setPrompting(false);
    }
  }, []);

  useEffect(() => {
    if (!enabled) {
      setLocked(false);
      return;
    }
    // Cold start prompt
    void unlock();
  }, [enabled, unlock]);

  useEffect(() => {
    const subscription = AppState.addEventListener("change", (nextState: AppStateStatus) => {
      setAppState(nextState);
      if (!enabledRef.current) return;

      if (nextState === "background") {
        backgroundTimeRef.current = Date.now();
      } else if (nextState === "active") {
        if (backgroundTimeRef.current) {
          const elapsed = Date.now() - backgroundTimeRef.current;
          backgroundTimeRef.current = null;

          if (elapsed > BACKGROUND_LOCK_THRESHOLD_MS) {
            setLocked(true);
            lockedRef.current = true;
            void unlock();
          }
        }
      }
    });

    return () => {
      subscription.remove();
    };
  }, [unlock]);

  // The re-lock decision lands in the same update as "active", so content never
  // shows for a frame between the cover lifting and the lock screen appearing.
  const contentHidden = enabled && (locked || appState === "inactive" || appState === "background");

  return { locked, contentHidden, prompting, unlock };
}

