@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Serif+Display:ital@0;1&display=swap");

:root {
  color-scheme: light dark;
  --ink: #202735;
  --muted: #626d80;
  --paper: #f7f9fd;
  --line: #dce3ef;
  --accent: #3260e8;
  --accent-dark: #294fc5;
  --button-ink: #ffffff;
  --surface: #ffffff;
  --surface-soft: #f0f4fc;
  --surface-tint: #e9effb;
  --shadow: #3260e81f;
  --tag-added-ink: #477043;
  --tag-added-surface: #dcecd6;
  --tag-fixed-ink: #a34830;
  --tag-fixed-surface: #fae0d2;
  --tag-improved-surface: #dce7ff;
  --tag-changed-ink: #64428a;
  --tag-changed-surface: #e8dff6;
  --tag-removed-ink: #9b4339;
  --tag-removed-surface: #f5e1de;
  --font-body: "DM Sans", sans-serif;
  --font-heading: "DM Serif Display", Georgia, serif;
  --max: 980px;
  --reading: 720px;
}
@media (prefers-color-scheme: dark) {
  :root {
    --ink: #d5d1ca;
    --muted: #aaa69f;
    --paper: #1c1b19;
    --line: #3b3935;
    --accent: #8daaff;
    --accent-dark: #a6bdff;
    --button-ink: #1c1b19;
    --surface: #232220;
    --surface-soft: #272522;
    --surface-tint: #2b2926;
    --shadow: #00000033;
    --tag-added-ink: #b1cda4;
