    --tag-fixed-ink: #efb49e;
    --tag-fixed-surface: #4a3226;
    --tag-improved-surface: #303d5b;
    --tag-changed-ink: #d3bcec;
    --tag-changed-surface: #3b304b;
    --tag-removed-ink: #efaaa1;
    --tag-removed-surface: #382321;
  }
}
* {
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
}
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 16px/1.7 var(--font-body);
  -webkit-text-size-adjust: 100%;
}
main {
  max-width: var(--max);
  margin: 0 auto;
  padding: 28px 28px 88px;
}
header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
header > a:last-child {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--muted);
  font-size: 13px;
  text-decoration: none;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  color: var(--ink);
  text-decoration: none;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.brand img {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  box-shadow: 0 3px 12px var(--shadow);
}
nav {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 18px;
  font-size: 13px;
}
nav a {
  color: var(--muted);
  text-decoration: none;
}
nav a:hover,
nav a:focus-visible,
header > a:last-child:hover {
  color: var(--accent-dark);
}
a {
  color: var(--accent-dark);
  text-underline-offset: 3px;
}

