const { width: SCREEN_WIDTH } = Dimensions.get("window");

const CHROME = "#FBFAF6";
const DELETE = "#F4B4B4";

export function ImageViewerModal({
  uris,
  initialIndex = 0,
  visible,
  onClose,
  onDelete,
}: ImageViewerModalProps) {
  const insets = useSafeAreaInsets();
  const appLocked = useAppLocked();
  const [index, setIndex] = useState(initialIndex);
  const [prevVisible, setPrevVisible] = useState(visible);
  const listRef = useRef<FlatList<string>>(null);

  // Reset to the tapped photo only when the caller opens the viewer. App lock
  // hides and re-shows the modal; that must return to the photo being viewed.
  if (visible !== prevVisible) {
    setPrevVisible(visible);
    if (visible) setIndex(initialIndex);
  }

  useEffect(() => {
    if (!visible) return;
    if (uris.length === 0) {
      onClose();
      return;
    }
    if (index >= uris.length) {
      setIndex(uris.length - 1);
    }
  }, [uris, visible, index, onClose]);

  const handleShow = () => {
    if (index > 0) {
      requestAnimationFrame(() => {
        listRef.current?.scrollToIndex({ index, animated: false });
      });
    }
  };

  const onMomentumScrollEnd = (event: NativeSyntheticEvent<NativeScrollEvent>) => {
    const nextIndex = Math.round(event.nativeEvent.contentOffset.x / SCREEN_WIDTH);
    setIndex(nextIndex);
  };

  const handleShare = () => {
    const uri = uris[index];
    if (uri) shareImage(uri);
  };

  const handleDelete = () => {
    if (!onDelete) return;
    Alert.alert("Delete this photo?", "This cannot be undone.", [
      { text: "Cancel", style: "cancel" },
      {
        text: "Delete",
        style: "destructive",
        onPress: () => onDelete(index),
      },
    ]);
  };

  return (
    <Modal
      visible={visible && !appLocked}
      transparent
      animationType="fade"
      onRequestClose={onClose}
      onShow={handleShow}
    >
      <View style={[styles.screen, { backgroundColor: "rgba(0,0,0,0.92)" }]}>
        <FlatList
          ref={listRef}
          data={uris}
          keyExtractor={(uri, itemIndex) => `${uri}-${itemIndex}`}
          horizontal
          pagingEnabled
          showsHorizontalScrollIndicator={false}
          initialScrollIndex={index > 0 ? index : undefined}
          getItemLayout={(_, itemIndex) => ({
            length: SCREEN_WIDTH,
            offset: SCREEN_WIDTH * itemIndex,
            index: itemIndex,
          })}
          onMomentumScrollEnd={onMomentumScrollEnd}
          renderItem={({ item }) => (
            <View style={styles.page}>
              <Image
                source={{ uri: item }}
                style={styles.image}
                contentFit="contain"
                accessibilityLabel="Full size entry image"
              />
            </View>
          )}
        />

        {onDelete ? (
          <Pressable
            onPress={handleDelete}
            hitSlop={space.md}
            style={[styles.iconBtn, { bottom: insets.bottom + space.lg, left: space.lg }]}
            accessibilityLabel="Delete photo"
            accessibilityRole="button"
          >
            <Feather name="trash-2" size={metrics.iconMd} color={DELETE} />
          </Pressable>
        ) : null}

        <Pressable
          onPress={handleShare}
          hitSlop={space.md}
          style={[styles.iconBtn, { bottom: insets.bottom + space.lg, right: space.lg }]}
          accessibilityLabel="Share photo"
          accessibilityRole="button"
        >
          <Feather name="share" size={metrics.iconMd} color={CHROME} />
        </Pressable>

        <Pressable
          onPress={onClose}
          hitSlop={space.md}
          style={[styles.iconBtn, { top: insets.top + space.sm, right: space.lg }]}
          accessibilityLabel="Close image"
          accessibilityRole="button"
        >
          <Feather name="x" size={metrics.iconMd} color={CHROME} />
        </Pressable>

        {uris.length > 1 ? (
          <ThemedText style={[styles.counter, { top: insets.top + space.sm, color: CHROME }]}>
            {index + 1} / {uris.length}
          </ThemedText>
        ) : null}
      </View>
    </Modal>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
    justifyContent: "center",
  },
  iconBtn: {
    position: "absolute",
    zIndex: 10,
    width: metrics.btnMd,
    height: metrics.btnMd,
    borderRadius: metrics.btnMd / 2,
    backgroundColor: "rgba(0,0,0,0.45)",
    alignItems: "center",
    justifyContent: "center",
  },
  counter: {
    position: "absolute",
    left: 0,
    right: 0,
    zIndex: 10,
    textAlign: "center",
    fontSize: 15,
    fontWeight: "500",
  },
  page: {
    width: SCREEN_WIDTH,
    height: "100%",
    justifyContent: "center",
  },
  image: {
    width: "100%",
    height: "100%",
  },
});

import { RecordingPresets } from "expo-audio";

/** Seconds to skip when using playback skip controls. */
export const PLAYBACK_SKIP_SECONDS = 10;

/** Polling interval for recording state updates (ms). */
export const RECORDING_POLL_MS = 100;

/** Polling interval for playback progress updates (ms). */
export const PLAYBACK_POLL_MS = 100;

/** Bars in timeline playback waveform. */
export const WAVEFORM_BAR_COUNT = 24;

/** Bars shown while recording (fewer = less visual noise). */
export const LIVE_WAVEFORM_BAR_COUNT = 18;

/** Recording preset with metering enabled for live level visualization. */
export const RECORDING_OPTIONS = {
  ...RecordingPresets.HIGH_QUALITY,
  isMeteringEnabled: true,
};

import Constants from "expo-constants";

export const APP_NAME: string = (Constants.expoConfig?.name as string) ?? "OpenLog";
export const APP_SLUG = APP_NAME.toLowerCase();
export const WEBSITE_URL = "https://rwitesh.github.io/openlog/";
export const CHANGELOG_URL = "https://rwitesh.github.io/openlog/changelog.html";
export const PRIVACY_POLICY_URL = "https://rwitesh.github.io/openlog/privacy-policy.html";
export const TERMS_URL = "https://rwitesh.github.io/openlog/terms.html";

