import type { EntrySearchResult } from "@/shared/types";
import { reportError } from "@/shared/utils/devLog";
import { runDb } from "./database";
import { type EntryRecord, getTagsByEntryIds, toEntry } from "./entries";

/** Match markers embedded in snippets by the SQL below; the UI splits on them to highlight. */
export const SNIPPET_MARK_START = "\u0001";
export const SNIPPET_MARK_END = "\u0002";

const MIN_QUERY_LENGTH = 2;
const SNIPPET_WORDS = 14;
const DEFAULT_LIMIT = 50;

interface SearchRecord extends EntryRecord {
  text_snippet: string | null;
  location_snippet: string | null;
}

/**
 * Transforms raw input into a safe FTS5 MATCH expression: every whitespace
 * token becomes a quoted prefix phrase (`"coffe"*`), so typing "tok" matches
 * "Tokyo" and punctuation is never parsed as FTS query syntax.
 */
export function toFtsMatchQuery(input: string): string | null {
  const tokens = input
    .replace(/"/g, " ")
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map((token) => `"${token}"*`);

  return tokens.length ? tokens.join(" ") : null;
}

/** Searches entry text, locations, and attached tags. */
export async function searchEntries(
  query: string,
  limit: number = DEFAULT_LIMIT
): Promise<EntrySearchResult[]> {
  const match = toFtsMatchQuery(query);
  if (!match || query.trim().length < MIN_QUERY_LENGTH) return [];
  const tagQuery = query.normalize("NFKC").trim().replace(/\s+/g, " ").toLocaleLowerCase("en-US");

  return runDb(async (db) => {
    let textMatches: SearchRecord[] = [];
    try {
      textMatches = await db.getAllAsync<SearchRecord>(
        `SELECT e.id, e.created_at, e.updated_at, e.text, e.images, e.audios, e.attachments,
                e.latitude, e.longitude, e.location,
                snippet(entries_fts, 0, char(1), char(2), '…', ${SNIPPET_WORDS}) AS text_snippet,
                snippet(entries_fts, 1, char(1), char(2), '…', ${SNIPPET_WORDS}) AS location_snippet
           FROM entries_fts
           JOIN entries e ON e.rowid = entries_fts.rowid
          WHERE entries_fts MATCH ?
          ORDER BY entries_fts.rank
          LIMIT ?`,
        match,
        limit
      );
    } catch (error) {
      // A failed FTS query must not hide otherwise valid tag matches.
      reportError("search:text", error);
    }

    let tagMatches: SearchRecord[] = [];
    try {
      tagMatches = await db.getAllAsync<SearchRecord>(
        `SELECT e.id, e.created_at, e.updated_at, e.text, e.images, e.audios, e.attachments,
                e.latitude, e.longitude, e.location, NULL AS text_snippet, NULL AS location_snippet
           FROM entries e
           JOIN entry_tags et ON et.entry_id = e.id
           JOIN tags t ON t.id = et.tag_id
          WHERE instr(t.key, ?) = 1
          ORDER BY e.created_at DESC, e.id DESC
          LIMIT ?`,
        tagQuery,
        limit
      );
    } catch (error) {
      reportError("search:tags", error);
    }

    try {
      const rows: SearchRecord[] = [];
      const textMatchesById = new Map(textMatches.map((row) => [row.id, row]));
      const seen = new Set<string>();
      // Tag matches take precedence so a full text result page cannot crowd out
      // entries found solely through a tag. Keep FTS snippets for overlaps.
      for (const tagMatch of tagMatches) {
        if (seen.has(tagMatch.id)) continue;
        seen.add(tagMatch.id);
        rows.push(textMatchesById.get(tagMatch.id) ?? tagMatch);
        if (rows.length === limit) break;
      }
      for (const row of textMatches) {
        if (seen.has(row.id)) continue;
        seen.add(row.id);
        rows.push(row);
        if (rows.length === limit) break;
      }

      const tagsByEntryId = await getTagsByEntryIds(
        db,
        rows.map((row) => row.id)
      );
      return rows.map((row) => ({
        entry: toEntry(row, tagsByEntryId.get(row.id)),
        snippet: row.text ? (row.text_snippet ?? "") : "",
        locationSnippet: row.location ? (row.location_snippet ?? "") : "",
      }));
    } catch (error) {
      reportError("search:results", error);
      return [];
    }
  });
}

import { Feather } from "@expo/vector-icons";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import {
  KeyboardAvoidingView,
  Platform,
  Pressable,
  StyleSheet,
  TextInput,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import type { RootStackParamList } from "@/navigation/types";
import { ThemedText } from "@/shared/components/ThemedText";
import { metrics, press, radius, space, typography, useTheme } from "@/theme";
import { type Step, useWelcomeAuth } from "./useWelcomeAuth";
import { WelcomeShowcase } from "./WelcomeShowcase";

type Props = NativeStackScreenProps<RootStackParamList, "Welcome">;

const CTA_BLUE = "#3663E9";

function headerFor(step: Step) {
  switch (step) {
    case "showcase":
      return {
        title: "Welcome",
        subtitle: "Your personal life timeline.",
      };
    case "name":
      return {
        title: "What should we call you?",
        subtitle: "Shown on your entries.",
      };
  }
}

export function WelcomeScreen({ navigation }: Props) {
  const { theme } = useTheme();
  const { colors } = theme;
  const insets = useSafeAreaInsets();

  const flow = useWelcomeAuth(navigation);
  const { step, name, canContinue, canGoBack } = flow;

  if (step === "showcase") {
    return <WelcomeShowcase onFinish={flow.finishShowcase} />;
  }

  const header = headerFor(step);

  return (
    <KeyboardAvoidingView
      style={styles.flex}
      behavior={Platform.OS === "ios" ? "padding" : undefined}
    >
      <View
        style={[
          styles.screen,
          {
            backgroundColor: colors.background,
            paddingTop: insets.top + space.md,
            paddingBottom: insets.bottom + space.xl,
          },
        ]}
      >
        {canGoBack && (
          <Pressable
            onPress={flow.goBackStep}
            style={({ pressed }) => [styles.backButton, pressed && press]}
            accessibilityRole="button"
            accessibilityLabel="Go back"
          >
            <Feather name="chevron-left" size={metrics.iconMd} color={colors.text} />
            <ThemedText style={[typography.settingLabel, { color: colors.text }]}>Back</ThemedText>
          </Pressable>
        )}

        <View style={styles.body}>
          <View style={styles.headerBlock}>
            <ThemedText
              weight="semibold"
              style={[typography.headerGreeting, { color: colors.text }]}
            >
              {header.title}
            </ThemedText>
            <ThemedText style={[typography.headerSubtitle, { color: colors.textSecondary }]}>
              {header.subtitle}
            </ThemedText>
          </View>

          <TextInput
            value={name}
            onChangeText={flow.setName}
            placeholder="Full name"
            placeholderTextColor={colors.textTertiary}
            autoCapitalize="words"
            autoCorrect={false}
            autoFocus
            returnKeyType="done"
            maxLength={40}
            onSubmitEditing={flow.submitStep}
            style={inputStyle(colors.text, colors.surfaceMuted, colors.separator)}
          />
        </View>

        <View style={styles.actions}>
          <Pressable
            onPress={flow.submitStep}
            disabled={!canContinue}
            style={({ pressed }) => [
              styles.ctaButton,
              !canContinue && styles.ctaDimmed,
              canContinue && pressed && press,
            ]}
            accessibilityLabel="Save"
            accessibilityRole="button"
            accessibilityState={{ disabled: !canContinue }}
          >
            <ThemedText weight="medium" style={[typography.settingLabel, { color: "#FFFFFF" }]}>
              Save
            </ThemedText>
          </Pressable>
        </View>
      </View>
    </KeyboardAvoidingView>
  );
}

function inputStyle(color: string, background: string, border: string) {
  return [
    styles.input,
    typography.headerSubtitle,
    { color, backgroundColor: background, borderColor: border },
  ];
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  screen: {
    flex: 1,
    paddingHorizontal: space.xxl,
  },
  backButton: {
    flexDirection: "row",
    alignItems: "center",
    gap: space.xs,
    alignSelf: "flex-start",
    paddingVertical: space.sm,
    paddingRight: space.lg,
  },
  body: {
    flex: 1,
    justifyContent: "center",
    gap: space.lg,
  },
  headerBlock: {
    gap: space.xs,
  },
  actions: {
    gap: space.md,
  },
  ctaButton: {
    height: metrics.btnMd + 8,
    borderRadius: radius.lg,
    borderWidth: StyleSheet.hairlineWidth,
    backgroundColor: CTA_BLUE,
    borderColor: CTA_BLUE,
    alignItems: "center",
    justifyContent: "center",
  },
  ctaDimmed: {
    opacity: 0.55,
  },
  input: {
    borderRadius: radius.md,
    borderWidth: StyleSheet.hairlineWidth,
    paddingHorizontal: space.lg,
    paddingVertical: space.md + 2,
    letterSpacing: 2,
  },
});

import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
import { useState } from "react";
import { analytics } from "@/config/analytics";
import { useProfile } from "@/modules/profile";
import type { RootStackParamList } from "@/navigation/types";
import { ONBOARDING_COMPLETED_KEY, setSetting } from "@/services/db/settings";
import { reportError } from "@/shared/utils";

type Navigation = NativeStackNavigationProp<RootStackParamList, "Welcome">;

export type Step = "showcase" | "name";

/** Marks onboarding done and leaves the Welcome screen. */
export function completeOnboarding(navigation: Navigation) {
  setSetting(ONBOARDING_COMPLETED_KEY, "1").catch((error) =>
    reportError("welcome:markDone", error)
  );
  if (navigation.canGoBack()) navigation.goBack();
  else navigation.replace("Timeline");
}

export function useWelcomeAuth(navigation: Navigation) {
  const { setName } = useProfile();
  const [step, setStep] = useState<Step>("showcase");
  const [name, setNameInput] = useState("");

  const finishShowcase = () => setStep("name");

  const goBackStep = () => setStep("showcase");

  const saveName = () => {
    const fullName = name.trim().replace(/\s+/g, " ");
    if (!fullName) return;
    setName(fullName);
    analytics.capture("onboarding_completed");
    completeOnboarding(navigation);
  };

  return {
    step,
    name,
    setName: setNameInput,
    canContinue: name.trim().length > 0,
    canGoBack: step === "name",
    finishShowcase,
    goBackStep,
    submitStep: step === "showcase" ? finishShowcase : saveName,
    exitToApp: () => completeOnboarding(navigation),
  };
}

import { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
import { AppState, type AppStateStatus } from "react-native";

import { analytics } from "@/config/analytics";
import { authenticate, getEnrolledAuthLevel } from "./auth";

const UNLOCK_REASON = "Unlock your entries";
const BACKGROUND_LOCK_THRESHOLD_MS = 60 * 1000; // 1 minute in background before re-locking

const AppLockedContext = createContext(false);

export const AppLockedProvider = AppLockedContext.Provider;

/**
 * True while the app is locked. Native modals draw in their own window above the
 * lock screen, so they must stop rendering while this holds. They deliberately
 * stay up through brief inactive states: dismissing a modal there interrupts
 * anything it presented (share sheet, permission alert) and resets its content.
 */
export function useAppLocked(): boolean {
  return useContext(AppLockedContext);
}

/**
 * Owns the app-lock gate:
 *   - opens locked and prompts while the lock is enabled
 *   - hides content whenever the app is not active; this renders from JS, so
 *     the OS may take its app-switcher snapshot before the cover lands
 *   - re-locks after > 60 seconds in background
 *   - opens directly when the device has no unlock method left, so the user
 *     is never trapped outside their data (the enabled preference is kept and
 *     the lock resumes once a screen lock exists again)
 */
export function useAppLock(enabled: boolean) {
  const [locked, setLocked] = useState(enabled);
  const [prompting, setPrompting] = useState(false);
  const [appState, setAppState] = useState<AppStateStatus>(AppState.currentState);

  const lockedRef = useRef(locked);
  const promptingRef = useRef(false);
  const enabledRef = useRef(enabled);
  const backgroundTimeRef = useRef<number | null>(null);

  lockedRef.current = locked;
  enabledRef.current = enabled;

  const unlock = useCallback(async () => {
    if (promptingRef.current || !lockedRef.current) return;

    promptingRef.current = true;
    setPrompting(true);

    try {
      if ((await getEnrolledAuthLevel()) === "none") {
        // Nothing on the device can verify the owner; prompting could never
        // succeed and reinstalling would destroy the local timeline.
        analytics.capture("app_lock_bypassed");
        setLocked(false);
        return;
      }

      if (await authenticate(UNLOCK_REASON)) {
        setLocked(false);
      }
    } finally {
      promptingRef.current = false;
      setPrompting(false);
    }
  }, []);

  useEffect(() => {
    if (!enabled) {
      setLocked(false);
      return;
    }
    // Cold start prompt
    void unlock();
  }, [enabled, unlock]);

  useEffect(() => {
    const subscription = AppState.addEventListener("change", (nextState: AppStateStatus) => {
      setAppState(nextState);
      if (!enabledRef.current) return;

      if (nextState === "background") {
        backgroundTimeRef.current = Date.now();
      } else if (nextState === "active") {
        if (backgroundTimeRef.current) {
          const elapsed = Date.now() - backgroundTimeRef.current;
          backgroundTimeRef.current = null;

          if (elapsed > BACKGROUND_LOCK_THRESHOLD_MS) {
            setLocked(true);
            lockedRef.current = true;
            void unlock();
          }
        }
      }
    });

    return () => {
      subscription.remove();
    };
  }, [unlock]);

  // The re-lock decision lands in the same update as "active", so content never
  // shows for a frame between the cover lifting and the lock screen appearing.
  const contentHidden = enabled && (locked || appState === "inactive" || appState === "background");

  return { locked, contentHidden, prompting, unlock };
}

import { getDocumentAsync } from "expo-document-picker";
import { Directory, File } from "expo-file-system";

import { logDevWarning } from "@/shared/utils/devLog";

import { ARCHIVE_EXTENSION } from "./types";

/**
 * Prompts user with the system file picker to select a backup archive.
 */
export async function pickBackupArchiveFile(): Promise<string | null> {
  const result = await getDocumentAsync({
    type: ["*/*", "application/octet-stream", "application/zip"],
    copyToCacheDirectory: true,
  });

  if (result.canceled || !result.assets?.[0]?.uri) return null;

  const asset = result.assets[0];
  const name = (asset.name || asset.uri).toLowerCase();
  if (!name.endsWith(ARCHIVE_EXTENSION) && !name.endsWith(`${ARCHIVE_EXTENSION}.zip`)) {
    throw new Error(`Select a valid ${ARCHIVE_EXTENSION} backup file.`);
  }

  return asset.uri;
}

/**
 * Prompts user to pick a folder upfront for backup storage.
 * Returns null if cancelled. Throws error if unsupported or picker fails.
 */
export async function pickBackupDestinationDirectory(): Promise<Directory | null> {
  try {
    const targetDir = await Directory.pickDirectoryAsync();
    if (!targetDir?.uri) return null;
    return targetDir;
  } catch (pickerErr) {
    if (
      pickerErr instanceof Error &&
      (/cancel/i.test(pickerErr.message) || /cancel/i.test(pickerErr.name))
    ) {
      return null;
    }
    throw pickerErr;
  }
}

/**
 * Copies a completed backup archive to a destination directory using native streaming,
 * then removes the temporary archive from cache.
 */
export async function copyBackupToDirectory(
  fileUri: string,
  filename: string,
  targetDir: Directory
): Promise<void> {
  const sourceFile = new File(fileUri);
  if (!sourceFile.exists) throw new Error("Backup file could not be found.");
  if (sourceFile.name !== filename) sourceFile.rename(filename);
  await sourceFile.copy(targetDir, { overwrite: true });
  try {
    sourceFile.delete();
  } catch (err) {
    logDevWarning("copyBackupToDirectory:deleteSource", err);
  }
}

