.note-kicker {
  margin: 0 0 22px;
  color: var(--accent-dark);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}
.note-row {
  display: grid;
  grid-template-columns: 30px 1fr;
  gap: 12px;
  align-items: center;
  padding: 14px 0;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.86rem;
  line-height: 1.4;
}
.note-mark {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--accent-dark);
  font-family: Georgia, serif;
  font-size: 13px;
}
.note-foot {
  margin: 25px 0 0;
  color: var(--muted);
  font-size: 0.82rem;
}
.play-store-button {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  min-height: 62px;
  padding: 12px 24px;
  border: 1px solid var(--accent);
  border-radius: 16px;
  background: var(--accent);
  color: var(--button-ink);
  font-weight: 700;
  text-decoration: none;
  box-shadow: 0 4px 12px var(--shadow);
  transition:
    background 0.18s ease,
    box-shadow 0.18s ease;
}
.play-store-button:hover {
  background: var(--accent-dark);
  border-color: var(--accent-dark);
  box-shadow: 0 6px 16px var(--shadow);
}
.android-icon {
  flex-shrink: 0;
}
.play-store-label {
