}
.play-store-kicker {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
}
@media (prefers-reduced-motion: reduce) {
  .play-store-button {
    transition: none;
  }
}
.rule {
  height: 1px;
  border: 0;
  margin: 0;
  background: var(--line);
}
.section-label {
  margin: 44px 0 20px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}
.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
